package com.example.lebiais.sonde

/**
 * Les règles de saisie de l'écran Saisie. Le clavier d'iOS n'est pas toujours
 * celui qu'on demande à une page web : on filtre donc aussi ce qui est tapé.
 */
object Saisies {
    fun numerique(texte: String): String = texte.filter { it in '0'..'9' }

    /** Chiffres et un seul séparateur, rendu en virgule. */
    fun decimal(texte: String): String {
        val sb = StringBuilder()
        var vu = false
        for (c in texte) when {
            c in '0'..'9' -> sb.append(c)
            (c == ',' || c == '.') && !vu -> { sb.append(','); vu = true }
        }
        return sb.toString()
    }

    /** Chiffres seulement, remis en jj/mm/aaaa, dix caractères au plus. */
    fun date(texte: String): String {
        val chiffres = numerique(texte).take(8)
        return buildString {
            chiffres.forEachIndexed { i, c ->
                if (i == 2 || i == 4) append('/')
                append(c)
            }
        }
    }

    /** Vide, ou une vraie date jj/mm/aaaa. */
    fun dateValide(texte: String): Boolean {
        if (texte.isEmpty()) return true
        val p = texte.split('/')
        if (p.size != 3 || p[0].length != 2 || p[1].length != 2 || p[2].length != 4) return false
        val j = p[0].toIntOrNull() ?: return false
        val m = p[1].toIntOrNull() ?: return false
        val a = p[2].toIntOrNull() ?: return false
        if (m !in 1..12 || j < 1) return false
        val bissextile = (a % 4 == 0 && a % 100 != 0) || a % 400 == 0
        val max = when (m) { 2 -> if (bissextile) 29 else 28; 4, 6, 9, 11 -> 30; else -> 31 }
        return j <= max
    }
}

private val MOTS_DU_BAS = listOf(
    "Pâturage de la Combe, rotation du mardi.", "Œil clair, appétit normal.", "À revoir après la tonte d'automne.",
    "Rien à signaler, déplacée avec le lot de l'Écot.", "Complément minéral distribué ce matin.",
)

/**
 * Une fiche de données au hasard pour les six champs de l'écran Saisie : nom, boucle (chiffres),
 * date (jj/mm/aaaa, toujours réelle), poids (décimal à virgule), notes, dernier champ.
 * La même graine rend toujours la même fiche ; chaque champ passe les filtres de [Saisies] sans changer.
 */
fun ficheAleatoire(graine: Int): List<String> {
    val hasard = kotlin.random.Random(graine)
    val bete = troupeauFictif(300)[hasard.nextInt(300)]
    val boucle = Saisies.numerique(bete.boucle)
    val annee = 2020 + hasard.nextInt(7)
    val mois = 1 + hasard.nextInt(12)
    val jour = 1 + hasard.nextInt(28)
    val date = Saisies.date(
        jour.toString().padStart(2, '0') + mois.toString().padStart(2, '0') + annee.toString(),
    )
    val poids = Saisies.decimal("${40 + hasard.nextInt(60)}.${hasard.nextInt(10)}")
    return listOf(bete.nom, boucle, date, poids, bete.note, MOTS_DU_BAS[hasard.nextInt(MOTS_DU_BAS.size)])
}

/**
 * La majuscule automatique, faite par le code. Le clavier d'iPadOS 16.7 ne capitalise pas le champ
 * de saisie caché de Compose, même avec `autocapitalize` posé sur le bon élément (rapports d'essai) :
 * l'application réelle ne peut donc pas compter sur lui.
 * Seule la partie NOUVELLE du texte (après le préfixe commun avec [ancien]) est touchée : on ne
 * réécrit jamais ce que l'utilisateur a déjà validé, et effacer ne capitalise rien.
 * [phrases] faux : chaque mot ; vrai : le début du texte et ce qui suit « . », « ! », « ? » ou une ligne.
 */
fun Saisies.majuscules(ancien: String, nouveau: String, phrases: Boolean): String {
    if (nouveau.length <= ancien.length && ancien.startsWith(nouveau)) return nouveau
    var commun = 0
    while (commun < ancien.length && commun < nouveau.length && ancien[commun] == nouveau[commun]) commun++
    val sb = StringBuilder(nouveau)
    for (i in commun until nouveau.length) {
        val c = nouveau[i]
        if (!c.isLetter() || !c.isLowerCase()) continue
        if (debutDeMot(nouveau, i, phrases)) sb[i] = c.uppercaseChar()
    }
    return sb.toString()
}

private fun debutDeMot(texte: String, i: Int, phrases: Boolean): Boolean {
    if (i == 0) return true
    var j = i - 1
    if (!phrases) return texte[j].isWhitespace() || texte[j] == '-' || texte[j] == '\''
    // phrases : on remonte les espaces ; début de texte, retour à la ligne ou ponctuation finale juste avant.
    while (j >= 0 && texte[j] == ' ') j--
    if (j < 0) return i > 0 && texte.substring(0, i).isBlank()
    return texte[j] == '.' || texte[j] == '!' || texte[j] == '?' || texte[j] == '\n'
}
