private class Fiche(val champs: List<String>)

// Gardés pour toute la vie de la page, pas pour celle de l'écran : revenir au menu ne les efface pas.
// Seul un rechargement de la page (par Safari, par « ↻ Màj ») les vide, ce que l'essai d'endurance veut voir.
private val fichesEnMemoire = mutableStateListOf<Fiche>()
private val valeursEnMemoire = mutableStateListOf("", "", "", "", "", "")

internal fun nombreFiches(): Int = fichesEnMemoire.size

// Les séries de fiches au hasard prennent leurs graines ici, à la suite : jamais deux fois la même fiche.
private var graineDesSeries = 1000

/**
 * Crée et enregistre [n] fiches au hasard (graines successives), comme autant de touches sur
 * « Enregistrer ». Mesure le temps de création et celui jusqu'à l'image suivante (l'écran redessiné),
 * l'écrit dans le relevé comme événement et dans les étapes du banc. Appelée aussi par le parcours (lot B) ;
 * [noter] faux : ni événement ni étape (les petits ajouts répétés de l'endurance).
 */
suspend fun creerFichesAuHasard(n: Int, noter: Boolean = true): ResultatEtape {
    val debut = Navigateur.msDepuisLancement()
    val nouvelles = fichesAuHasard(n, graineDesSeries).map { Fiche(it) }
    graineDesSeries += n
    fichesEnMemoire.addAll(nouvelles)
    val cree = Navigateur.msDepuisLancement() - debut
    withFrameNanos { }
    val affiche = Navigateur.msDepuisLancement() - debut
    val resultat = ResultatEtape(
        "$n fiches au hasard", "fini",
        listOf(
            "création et enregistrement" to "${cree.toLong()} ms",
            "jusqu'à l'image suivante" to "${affiche.toLong()} ms",
            "fiches en mémoire" to "${fichesEnMemoire.size}",
        ),
    )
    if (noter) {
        Banc.evenement("$n fiches au hasard en ${cree.toLong()} ms (image suivante à ${affiche.toLong()} ms), ${fichesEnMemoire.size} en mémoire")
        Banc.noterEtape(resultat)
    }
    return resultat
}
/**
 * La dernière mesure du clavier faite par l'écran Saisie : le champ touché est-il entier au-dessus du
 * clavier ? Celle du DERNIER champ (tout en bas, le cas difficile de la grille) est gardée à part.
 */
object ClavierMesure {
    var derniere by mutableStateOf<MesureClavier?>(null)
    var dernierChamp by mutableStateOf<MesureClavier?>(null)

    fun noter(champ: String, mesure: MesureClavier) {
        derniere = meilleureMesureClavier(derniere, mesure)
        if (champ.startsWith("Dernier champ")) dernierChamp = meilleureMesureClavier(dernierChamp, mesure)
        if (mesure.clavierPx > 0) Banc.evenement("clavier : « $champ » ${mesure.enTexte()}")
    }
}

/** Réglage : la sonde capitalise elle-même Nom, Notes et le dernier champ (par défaut : oui). */
const val REGLAGE_MAJUSCULES_CODE = "majusculesCode"

internal fun viderFiches() {
    fichesEnMemoire.clear()
    for (i in valeursEnMemoire.indices) valeursEnMemoire[i] = ""
}

/**
 * Six champs, dont un collé au bas de l'écran. Quand un champ a le focus, une
 * réserve s'ouvre sous le dernier et le champ actif est ramené à l'écran une
 * fois le clavier monté. Le clavier d'iOS ne rétrécit pas la page : index.html
 * ajuste la hauteur de la zone sur `visualViewport`, d'où la réserve modeste.
 */
@OptIn(ExperimentalFoundationApi::class)
@Composable
fun EcranSaisie() {
    val libelles = listOf("Nom", "Boucle (numérique)", "Date (jj/mm/aaaa)", "Poids (décimal)", "Notes", "Dernier champ, collé au bas")
    val claviers = listOf(KeyboardType.Text, KeyboardType.Number, KeyboardType.Number, KeyboardType.Decimal, KeyboardType.Text, KeyboardType.Text)
    val majuscules = listOf(
        KeyboardCapitalization.Words, KeyboardCapitalization.None, KeyboardCapitalization.None,
        KeyboardCapitalization.None, KeyboardCapitalization.Sentences, KeyboardCapitalization.Sentences,
    )
    // inputmode et autocapitalize du DOM, posés à la main (Compose ne les transmet pas toujours à iOS).
    val modesDom = listOf("text" to "words", "numeric" to "none", "numeric" to "none", "decimal" to "none", "text" to "sentences", "text" to "sentences")
    val lignes = listOf(1, 1, 1, 1, 4, 1)
    val valeurs = valeursEnMemoire
    val fiches = fichesEnMemoire
    var focus by remember { mutableStateOf<Int?>(null) }
    var clavier by remember { mutableStateOf(0.0) }
    var majusculesCode by remember { mutableStateOf(Navigateur.lireReglage(REGLAGE_MAJUSCULES_CODE) != "0") }
    var mesures by remember { mutableStateOf("") }
    val demandeurs = remember { List(6) { BringIntoViewRequester() } }

    // Hauteur du clavier lue sur le navigateur (innerHeight − visualViewport) : la place est réservée ici.
    LaunchedEffect(Unit) {
        while (true) {
            clavier = Navigateur.hauteurClavier()
            mesures = Navigateur.mesuresClavier()
            delay(150)
        }
    }
    // Le clavier met un moment à monter : on ramène le champ à chaque changement de sa hauteur.
    // Puis on mesure (passivement) si le champ touché est entier au-dessus du clavier : noté pour le rapport.
    val bornes = remember { arrayOfNulls<Rect>(6) }
    val densite = LocalDensity.current.density
    LaunchedEffect(focus, clavier.toInt() / 40) {
        val f = focus ?: return@LaunchedEffect
        delay(250)
        demandeurs[f].bringIntoView()
        delay(400)
        val b = bornes[f] ?: return@LaunchedEffect
        val zone = lireZoneVisible(Navigateur.zoneVisible()) ?: return@LaunchedEffect
        ClavierMesure.noter(libelles[f], mesurerClavier(b.top / densite.toDouble(), b.bottom / densite.toDouble(), zone.first, zone.second, Navigateur.hauteurClavier()))
    }

    fun filtrer(i: Int, texte: String): String = when (i) {
        1 -> Saisies.numerique(texte)
        2 -> Saisies.date(texte)
        3 -> Saisies.decimal(texte)
        // Nom : chaque mot ; Notes et dernier champ : chaque phrase. Le clavier d'iPadOS 16.7 ne le fait pas
        // dans le champ caché de Compose (rapports d'essai) : c'est le code qui le fait, si l'interrupteur est actif.
        0 -> if (majusculesCode) Saisies.majuscules(valeurs[0], texte, phrases = false) else texte
        4, 5 -> if (majusculesCode) Saisies.majuscules(valeurs[i], texte, phrases = true) else texte
        else -> texte
    }

    @Composable
    fun champ(i: Int) {
        val faux = i == 2 && !Saisies.dateValide(valeurs[i])
        TextField(
            value = valeurs[i],
            onValueChange = { valeurs[i] = filtrer(i, it) },
            label = { Text(libelles[i]) },
            minLines = lignes[i],
            isError = faux,
            supportingText = if (i == 2) {
                { Text(if (faux) "Date impossible : jj/mm/aaaa" else "Chiffres seulement, les / se placent seuls") }
            } else null,
            keyboardOptions = KeyboardOptions(keyboardType = claviers[i], capitalization = majuscules[i]),
            modifier = Modifier.fillMaxWidth().padding(vertical = 6.dp)
                .bringIntoViewRequester(demandeurs[i])
                .modeClavierAuToucher(modesDom[i].first, modesDom[i].second)
                .onGloballyPositioned { bornes[i] = it.boundsInWindow() }
                .onFocusChanged { e ->
                    if (e.isFocused) {
                        focus = i
                        Navigateur.modeClavier(modesDom[i].first, modesDom[i].second)
                    } else if (focus == i) focus = null
                },
        )
    }

    // La zone qui défile s'arrête au-dessus du clavier : bringIntoView compte alors la place réellement visible.
    Column(Modifier.fillMaxSize().padding(bottom = clavier.dp).verticalScroll(rememberScrollState()).padding(16.dp)) {
        Text("Essayez : accents (é, è, ç, œ), majuscule automatique (Nom, Notes), clavier numérique et décimal, date, correction automatique, copier-coller, dictée.")
        androidx.compose.foundation.layout.Row(verticalAlignment = androidx.compose.ui.Alignment.CenterVertically) {
            androidx.compose.material3.Switch(
                checked = majusculesCode,
                onCheckedChange = {
                    majusculesCode = it
                    Navigateur.ecrireReglage(REGLAGE_MAJUSCULES_CODE, if (it) "1" else "0")
                    Banc.evenement("majuscules faites par le code : " + if (it) "activées" else "désactivées (clavier seul)")
                },
            )
            Text("  Majuscules faites par la sonde (le clavier d'iPadOS ne les fait pas ici)", fontSize = 13.sp)
        }
        Text("Mesures du clavier : $mesures · réservé ${clavier.toInt()} px", color = androidx.compose.ui.graphics.Color(0xFF7A6F60))
        // Une fiche de données au hasard, pour remplir vite et enchaîner les enregistrements.
        var graine by remember { mutableStateOf(1) }
        OutlinedButton(
            onClick = {
                val f = ficheAleatoire(graine++)
                for (i in f.indices) valeurs[i] = f[i]
            },
            modifier = Modifier.padding(vertical = 8.dp),
        ) { Text("Remplir au hasard") }
        // Des fiches créées et enregistrées d'un coup, pour charger la mémoire et mesurer.
        val scope = rememberCoroutineScope()
        var serie by remember { mutableStateOf("") }
        var enCours by remember { mutableStateOf(false) }
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            for (n in listOf(10, 100)) {
                OutlinedButton(
                    enabled = !enCours,
                    onClick = {
                        enCours = true
                        scope.launch {
                            try {
                                val r = creerFichesAuHasard(n)
                                serie = "${r.nom} : " + r.mesures.joinToString(" · ") { "${it.first} ${it.second}" }
                            } finally { enCours = false }
                        }
                    },
                ) { Text("$n fiches au hasard") }
            }
        }
        if (serie.isNotEmpty()) Text(serie, color = androidx.compose.ui.graphics.Color(0xFF7A6F60))
        for (i in 0..4) champ(i)
        Button(
            onClick = {
                fiches.add(Fiche(valeurs.toList()))
                for (i in valeurs.indices) valeurs[i] = ""
            },
            modifier = Modifier.padding(vertical = 8.dp),
        ) { Text("Enregistrer") }
        Text("${fiches.size} fiche(s) en mémoire")
        Spacer(Modifier.height(280.dp))
        champ(5)
        Spacer(Modifier.height(24.dp))
    }
}
