package com.example.lebiais.sonde

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

// L'état du parcours automatique (lot B) et ses mesures : logique pure, sans navigateur.
// L'avancement est gardé en localStorage (réglage « parcours ») à chaque étape et chaque minute :
// si iOS décharge la page, le lancement suivant le retrouve et propose le rapport partiel.

/** Les images par seconde d'une fenêtre de temps : moyenne des secondes pleines, pire seconde, plus longue pause. */
@Serializable
data class FluiditeMesuree(val moyenne: Int, val min: Int, val pauseMaxMs: Int, val secondes: Int) {
    fun enTexte(): String = "moyenne $moyenne i/s · pire $min i/s · pause max $pauseMaxMs ms · $secondes s mesurées"
}

/**
 * Une fenêtre de mesure branchée sur la boucle d'images de `Sonde()` (voir `Fluidite.fenetres`) :
 * elle reçoit chaque seconde pleine et chaque pause entre deux images, page cachée exclue.
 */
class FenetreMesure {
    private var somme = 0L
    private var secondes = 0
    private var min = Int.MAX_VALUE
    private var pauseMax = 0

    fun noterSeconde(fps: Int) {
        somme += fps
        secondes++
        if (fps < min) min = fps
    }

    fun noterPause(ms: Int) { if (ms > pauseMax) pauseMax = ms }

    fun resultat(): FluiditeMesuree =
        if (secondes == 0) FluiditeMesuree(0, 0, pauseMax, 0)
        else FluiditeMesuree((somme / secondes).toInt(), min, pauseMax, secondes)
}

/** Le temps de remplissage de la carte après chaque déplacement : null quand l'attente a expiré. */
data class Remplissage(val medianeMs: Int?, val pireMs: Int?, val nonRemplis: Int, val nombre: Int) {
    fun enTexte(): String =
        if (medianeMs == null) "aucun remplissage mesuré ($nombre déplacements, $nonRemplis non remplis)"
        else "médiane $medianeMs ms · pire $pireMs ms · $nombre déplacements · $nonRemplis non rempli" + if (nonRemplis > 1) "s" else ""
}

fun resumeRemplissage(tempsMs: List<Double?>): Remplissage {
    val mesures = tempsMs.filterNotNull().sorted()
    val nonRemplis = tempsMs.size - mesures.size
    if (mesures.isEmpty()) return Remplissage(null, null, nonRemplis, tempsMs.size)
    val m = mesures.size / 2
    val mediane = if (mesures.size % 2 == 1) mesures[m] else (mesures[m - 1] + mesures[m]) / 2
    return Remplissage(mediane.toInt(), mesures.last().toInt(), nonRemplis, tempsMs.size)
}

/** Un point de contrôle de l'endurance, un par minute ; écrit aussi dans le relevé. */
@Serializable
data class PointDeControle(
    val minute: Int,
    val fps: Int,
    val fpsMin: Int,
    val pauseMaxMs: Int,
    val photos: Int,
    val fiches: Int,
    val decodesMo: Int,
    val tuilesRecues: Int,
    val tuilesRefusees: Int,
    val chargement: Int,
    val orientation: String = "",
) {
    fun enTexte(): String = "min $minute : " + mesure()

    /** Le texte sans la minute (pour les mesures du rapport, dont la clé est la minute). */
    fun mesure(): String =
        "$fps i/s (pire $fpsMin) · pause max $pauseMaxMs ms · $photos photos · $fiches fiches · $decodesMo Mo décodés · " +
            "tuiles $tuilesRecues reçues / $tuilesRefusees refusées · chargement n° $chargement" +
            if (orientation.isNotBlank()) " · $orientation" else ""
}

/** Une étape faite : son nom, sa conclusion, sa durée réelle et ses mesures. */
@Serializable
data class EtapeFaite(val nom: String, val conclusion: String, val dureeS: Int, val mesures: List<Pair<String, String>> = emptyList())

/** Le champ touché est-il entièrement au-dessus du clavier ? Positions en px CSS. */
@Serializable
data class MesureClavier(
    val visible: Boolean,
    val champHaut: Int,
    val champBas: Int,
    val zoneHaut: Int,
    val zoneBas: Int,
    val clavierPx: Int,
) {
    fun enTexte(): String =
        "visible : ${if (visible) "oui" else "non"} (champ $champHaut–$champBas px, zone visible $zoneHaut–$zoneBas px, clavier $clavierPx px)"
}

/**
 * Entre l'ancienne mesure et la nouvelle, celle à garder : une mesure prise sans clavier (le champ
 * touché avant qu'il monte, ou après qu'il est retombé) n'écrase pas une mesure faite clavier ouvert,
 * la seule qui prouve quelque chose.
 */
fun meilleureMesureClavier(ancienne: MesureClavier?, nouvelle: MesureClavier): MesureClavier =
    if (nouvelle.clavierPx <= 0 && ancienne != null && ancienne.clavierPx > 0) ancienne else nouvelle

/**
 * Le champ [champHaut]..[champBas] (px CSS, depuis le haut de la page) est visible s'il tient dans la
 * partie visible de la page, de [zoneDecalage] à [zoneDecalage] + [zoneHauteur] (visualViewport). Un px de tolérance.
 */
fun mesurerClavier(champHaut: Double, champBas: Double, zoneDecalage: Double, zoneHauteur: Double, clavierPx: Double): MesureClavier {
    val zoneBas = zoneDecalage + zoneHauteur
    val visible = champHaut >= zoneDecalage - 1 && champBas <= zoneBas + 1
    return MesureClavier(visible, champHaut.toInt(), champBas.toInt(), zoneDecalage.toInt(), zoneBas.toInt(), clavierPx.toInt())
}

/** « décalage|hauteur|innerHeight » de `sonde.zoneVisible()` ; null si illisible. */
fun lireZoneVisible(texte: String): Pair<Double, Double>? {
    val p = texte.split('|')
    if (p.size < 2) return null
    val decalage = p[0].toDoubleOrNull() ?: return null
    val hauteur = p[1].toDoubleOrNull() ?: return null
    return decalage to hauteur
}

/** Tout ce que les verdicts lisent ; rempli étape par étape, gardé avec l'avancement. */
@Serializable
data class DonneesParcours(
    // Stockage
    val ecritureOk: Boolean? = null,
    val ecritureDetail: String = "",
    val relectureIntacte: Boolean? = null,
    val relectureDetail: String = "",
    val persistance: String = "",
    val estimation: String = "",
    val ancienneEcriture: String = "",
    val ancienneAgeJours: Int? = null,
    val ancienneIntacte: Boolean? = null,
    // Fluidité
    val liste: FluiditeMesuree? = null,
    val listeBetesVues: Int = 0,
    val carte: FluiditeMesuree? = null,
    val remplissagesMs: List<Double?> = emptyList(),
    val tuilesRecues: Int = 0,
    val tuilesRefusees: Int = 0,
    // Endurance
    val enduranceS: Int = 0,
    val endurancePauseMaxMs: Int? = null,
    // Ouverture, téléchargement
    val ouvertureMs: Double? = null,
    val precacheJson: String = "",
    val tailleTransferee: String = "",
    /** « orientation : haut H · bas B · gauche G · droite D », une ligne par orientation vue. */
    val marges: List<String> = emptyList(),
    val margeMaxPx: Int = 0,
    // Fiches et photos
    val fichesVoulues: Int = 0,
    val fichesCreees: Int = 0,
    val fichesErreur: String = "",
    val photosVoulues: Int = 0,
    val photosFaites: Int = 0,
    val photosArret: String = "",
    val decodesMaxMo: Int = 0,
    // Humain
    val clavier: MesureClavier? = null,
    /** Question (nom de l'enum) → réponse (nom de l'enum). */
    val reponses: Map<String, String> = emptyMap(),
) {
    /** Les réponses relues ; une clé inconnue (ancien build) est ignorée. */
    fun reponsesLues(): Map<Question, Reponse> = reponses.mapNotNull { (q, r) ->
        val question = Question.entries.firstOrNull { it.name == q } ?: return@mapNotNull null
        val reponse = Reponse.entries.firstOrNull { it.name == r } ?: return@mapNotNull null
        question to reponse
    }.toMap()
}

const val PARCOURS_EN_COURS = "en cours"
const val PARCOURS_FINI = "fini"
const val PARCOURS_ARRETE = "arrêté"

/** L'avancement du parcours, tel qu'il est gardé dans localStorage. */
@Serializable
data class Avancement(
    val plan: PlanParcours,
    val debutEpochMs: Double,
    val derniereMajEpochMs: Double,
    val dateDebut: String,
    val chargementAuDebut: Int,
    /** Le rang de l'étape en cours dans le plan (plan.etapes.size quand les mesures sont finies). */
    val indexEtape: Int = 0,
    val etat: String = PARCOURS_EN_COURS,
    val ecranAllume: String = "",
    val installation: String = "",
    val iosIndique: String = "",
    val etapes: List<EtapeFaite> = emptyList(),
    val points: List<PointDeControle> = emptyList(),
    val donnees: DonneesParcours = DonneesParcours(),
) {
    fun etapeCourante(): String = plan.etapes.getOrNull(indexEtape)?.etape?.nom ?: "questions de fin"
    fun enJson(): String = JSON_AVANCEMENT.encodeToString(serializer(), this)
    /** Minutes écoulées entre le lancement et la dernière sauvegarde. */
    fun minutes(): Int = ((derniereMajEpochMs - debutEpochMs) / 60_000).toInt()
}

private val JSON_AVANCEMENT = Json { ignoreUnknownKeys = true; encodeDefaults = true }

/** L'avancement gardé ; null s'il n'y en a pas ou s'il est illisible (ancien format). */
fun lireAvancement(json: String): Avancement? {
    if (json.isBlank()) return null
    return try {
        JSON_AVANCEMENT.decodeFromString(Avancement.serializer(), json)
    } catch (e: Exception) {
        null
    }
}

/** Un parcours resté « en cours » dans un autre chargement de la page : iOS l'a déchargée, ou on l'a rechargée. */
data class Interruption(val etape: String, val minutes: Int, val chargementAvant: Int, val chargementApres: Int) {
    fun message(): String =
        "Un parcours a été interrompu à l'étape « $etape » après $minutes min " +
            "(la page a été rechargée : chargement n° $chargementAvant, puis n° $chargementApres)."
}

fun interruption(avancement: Avancement?, chargementCourant: Int): Interruption? {
    val av = avancement ?: return null
    if (av.etat != PARCOURS_EN_COURS || av.chargementAuDebut == chargementCourant) return null
    return Interruption(av.etapeCourante(), av.minutes(), av.chargementAuDebut, chargementCourant)
}

/** Le numéro du jour (jours depuis le 1er janvier 1970) d'une date du calendrier grégorien. */
private fun numeroDuJour(annee: Int, mois: Int, jour: Int): Long {
    val a = if (mois <= 2) annee - 1 else annee
    val ere = (if (a >= 0) a else a - 399) / 400
    val ae = a - ere * 400
    val m = mois
    val jourDeLAnnee = (153 * (if (m > 2) m - 3 else m + 9) + 2) / 5 + jour - 1
    val jourDeLEre = ae * 365 + ae / 4 - ae / 100 + jourDeLAnnee
    return ere * 146097L + jourDeLEre - 719468
}

/** Jours pleins entre « jj/mm/aaaa … » (date de dernière écriture) et « aaaa-mm-jj … » (aujourd'hui) ; null si illisible. */
fun joursEntre(dateFr: String, aujourdhuiIso: String): Int? {
    val fr = Regex("""^(\d{1,2})/(\d{1,2})/(\d{4})""").find(dateFr.trim())?.groupValues ?: return null
    val iso = Regex("""^(\d{4})-(\d{2})-(\d{2})""").find(aujourdhuiIso.trim())?.groupValues ?: return null
    val avant = numeroDuJour(fr[3].toInt(), fr[2].toInt(), fr[1].toInt())
    val apres = numeroDuJour(iso[1].toInt(), iso[2].toInt(), iso[3].toInt())
    return (apres - avant).toInt()
}

/** L'ouverture la plus récente faite hors ligne (navigator.onLine faux au chargement), gardée dans localStorage. */
data class OuvertureHorsLigne(val date: String, val ms: Long, val chargement: Int) {
    fun enTexte(): String = "$date|$ms|$chargement"
}

fun lireOuvertureHorsLigne(texte: String): OuvertureHorsLigne? {
    val p = texte.split('|')
    if (p.size != 3 || p[0].isBlank()) return null
    return OuvertureHorsLigne(p[0], p[1].toLongOrNull() ?: return null, p[2].toIntOrNull() ?: return null)
}

/**
 * Les étapes du rapport : le résumé du parcours (durée, plan prévu et suivi, écran allumé, chargements),
 * chaque étape faite, les points de contrôle de l'endurance, les réponses aux questions.
 */
fun etapesDuRapport(av: Avancement, chargementCourant: Int): List<ResultatEtape> {
    val recharge = chargementCourant != av.chargementAuDebut
    val conclusion = when {
        av.etat == PARCOURS_FINI -> "fini"
        av.etat == PARCOURS_ARRETE -> "arrêté par le testeur à l'étape « ${av.etapeCourante()} » après ${av.minutes()} min"
        recharge -> "interrompu à l'étape « ${av.etapeCourante()} » après ${av.minutes()} min : la page a été rechargée (iOS décharge les pages sous pression mémoire ; information, pas un échec en soi)"
        else -> "en cours à l'étape « ${av.etapeCourante()} »"
    }
    val resume = ResultatEtape(
        "Parcours automatique", conclusion,
        listOf(
            "Durée choisie" to "${av.plan.dureeMin} min",
            "Lancé le" to av.dateDebut,
            "Plan prévu" to av.plan.enTexte(),
            "Plan suivi" to av.etapes.joinToString(" · ") { "${it.nom} ${it.dureeS} s" }.ifEmpty { "aucune étape finie" },
            "Écran allumé au lancement" to av.ecranAllume.ifBlank { "non noté" },
            "Installation au lancement" to av.installation.ifBlank { "non notée" },
            "Version d'iOS indiquée" to av.iosIndique.ifBlank { "non indiquée" },
            "Chargements" to "n° ${av.chargementAuDebut} au lancement, n° $chargementCourant maintenant : " +
                if (recharge) "la page a été rechargée pendant le parcours" else "pas de rechargement",
        ),
    )
    val etapes = av.etapes.map { ResultatEtape(it.nom, it.conclusion, listOf("durée réelle" to "${it.dureeS} s") + it.mesures) }
    val points = if (av.points.isEmpty()) emptyList() else listOf(
        ResultatEtape("Endurance — points de contrôle (${av.points.size})", "un par minute", av.points.map { "min ${it.minute}" to it.mesure() }),
    )
    val reponses = av.donnees.reponsesLues()
    val questions = ResultatEtape(
        "Questions rapides",
        if (reponses.isEmpty()) "pas de réponse" else "${reponses.size} réponse(s) sur ${Question.entries.size}",
        Question.entries.map { it.libelle to (reponses[it]?.libelle ?: "sans réponse") } +
            listOf("Dernier champ au-dessus du clavier (mesuré)" to (av.donnees.clavier?.enTexte() ?: "non mesuré")),
    )
    return listOf(resume) + etapes + points + questions
}
