package com.example.lebiais.sonde

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableIntStateOf
import androidx.compose.runtime.setValue
import androidx.compose.ui.graphics.ImageBitmap

/** Une tuile gardée : son image, ou null quand elle a été refusée (à telle heure, après tant d'essais). */
internal class Gardee(val image: ImageBitmap?, val refuseeA: Double = 0.0, val essais: Int = 0)

/** Une tuile refusée n'est redemandée qu'après ce délai (ms), et au plus [ESSAIS_MAX] fois. */
internal const val DELAI_NOUVEL_ESSAI_MS = 4000.0
internal const val ESSAIS_MAX = 3

/**
 * La mémoire des tuiles : [capacite] au plus. Quand elle est pleine, part d'abord la plus ancienne des
 * tuiles que l'écran ne montre plus ; une tuile à l'écran ne part que si toutes les autres y sont aussi.
 * Une tuile refusée (réseau, CORS) n'est pas condamnée : elle est redemandée après quatre secondes,
 * trois fois au plus.
 */
internal class MemoireTuiles(private val capacite: Int = 200) {
    private val gardees = LinkedHashMap<String, Gardee>()
    private val enCours = HashSet<String>()
    private var voulues: Set<String> = emptySet()
    var version by mutableIntStateOf(0)
    var recues by mutableIntStateOf(0)
    var refusees by mutableIntStateOf(0)

    /** Les tuiles que l'écran montre en ce moment. */
    fun voulues(cles: Set<String>) { voulues = cles }
    fun estVoulue(cle: String): Boolean = cle in voulues
    fun taille(): Int = gardees.size
    fun lire(cle: String): Gardee? = gardees[cle]

    /** Vrai quand chaque tuile à l'écran est arrivée, reçue ou refusée : la carte a fini de se remplir. */
    fun toutesArrivees(): Boolean = voulues.all { it in gardees }

    /** Vrai si la tuile doit partir au téléchargement maintenant. */
    fun demander(cle: String, maintenantMs: Double): Boolean {
        if (cle in enCours) return false
        val g = gardees[cle]
        if (g != null) {
            if (g.image != null) return false
            if (g.essais >= ESSAIS_MAX || maintenantMs - g.refuseeA < DELAI_NOUVEL_ESSAI_MS) return false
        }
        return enCours.add(cle)
    }

    /** Le tour de la tuile est venu et elle n'est plus voulue : on oublie la demande, sans rien garder. */
    fun abandonner(cle: String) { enCours.remove(cle) }

    fun ranger(cle: String, image: ImageBitmap?, maintenantMs: Double) {
        enCours.remove(cle)
        val essais = (gardees[cle]?.essais ?: 0) + 1
        gardees.remove(cle) // une tuile rangée de nouveau repasse en fin de file
        gardees[cle] = if (image != null) Gardee(image) else Gardee(null, maintenantMs, essais)
        if (image != null) recues++ else refusees++
        while (gardees.size > capacite) {
            val victime = gardees.keys.firstOrNull { it !in voulues } ?: gardees.keys.first()
            gardees.remove(victime)
        }
        version++
    }
}
