package com.example.lebiais.sonde

import androidx.compose.runtime.mutableStateListOf
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive

// Le rapport tel que le navigateur le voit maintenant, et son export. C'est ici
// que le parcours automatique (lot B) se branche :
//   Banc.noterEtape(…) / Banc.evenement(…)       pendant le parcours
//   Navigateur.ecranAllumeDemander()              au lancement du parcours
//   val r = rapportCourant(verdicts = …)          à la fin
//   ExportRapport.envoyer(r) / copier(r) / partager(r)

/** Ce que les outils de test et le parcours notent pendant la session (perdu au rechargement, comme le reste). */
object Banc {
    /** Les étapes de la session, dans l'ordre : reprises par `rapportCourant`. */
    val resultats = mutableStateListOf<ResultatEtape>()

    fun noterEtape(resultat: ResultatEtape) { resultats.add(resultat) }

    /** Écrit un événement dans le relevé (ignoré si la page est cachée, comme les échantillons). */
    fun evenement(texte: String) = Navigateur.releveAjouter(ligneEvenement(Navigateur.heure(), texte))

    /** Réglages du testeur, gardés dans localStorage et repris dans chaque rapport. */
    const val REGLAGE_TESTEUR = "testeur"
    /** La remarque libre, gardée tant qu'elle n'est pas envoyée. */
    const val REGLAGE_REMARQUE = "remarque"
    const val REGLAGE_IOS = "iosIndique"
}

/** L'environnement brut de `sonde.environnement()`, clé → valeur. */
fun environnementBrut(): Map<String, String> = try {
    Json.parseToJsonElement(Navigateur.environnement()).jsonObject.mapValues { it.value.jsonPrimitive.content }
} catch (e: Exception) {
    emptyMap()
}

/** L'appareil lu dans le user agent, platform et maxTouchPoints. */
fun appareilCourant(brut: Map<String, String> = environnementBrut()): Appareil =
    analyserAppareil(brut["userAgent"] ?: Navigateur.userAgent(), brut["platform"] ?: "", brut["maxTouchPoints"]?.toIntOrNull() ?: 0)

/** L'état du verrou d'écran, avec le mode d'affichage et la réserve d'iOS. */
fun etatEcranAllume(appareil: Appareil = appareilCourant()): String =
    messageEcranAllume(Navigateur.ecranAllumeEtat(), Navigateur.estInstallee(), appareil)

/** Les lignes « Environnement » du rapport. Interroge le Service Worker et le stockage : quelques centaines de ms. */
suspend fun environnementDuRapport(brut: Map<String, String> = environnementBrut()): List<Pair<String, String>> {
    val appareil = appareilCourant(brut)
    val m = Navigateur.margesSures()
    val ouverture = Ouverture.maintenant
    return listOf(
        "Version de la sonde" to "${Navigateur.version}, build ${Navigateur.build()}",
        "Appareil (user agent)" to appareil.resume(),
        "User agent" to (brut["userAgent"] ?: Navigateur.userAgent()),
        "navigator.platform" to (brut["platform"] ?: "?"),
        "maxTouchPoints" to (brut["maxTouchPoints"] ?: "?"),
        "Écran" to (brut["ecran"] ?: "?"),
        "devicePixelRatio" to (brut["dpr"] ?: "?"),
        "Cœurs (hardwareConcurrency)" to (brut["coeurs"] ?: "?"),
        "Mémoire (deviceMemory)" to (brut["memoire"] ?: "?"),
        "Langue" to (brut["langue"] ?: "?"),
        "Affichage" to (brut["affichage"] ?: "?"),
        "Orientation" to (brut["orientation"] ?: "?"),
        "Marges sûres (px)" to "haut ${m.haut.toInt()} · bas ${m.bas.toInt()} · gauche ${m.gauche.toInt()} · droite ${m.droite.toInt()}",
        "Service Worker" to Navigateur.etatServiceWorker(),
        "Précache" to lireControlePrecache(Navigateur.controlePrecache()),
        "Stockage" to "${Navigateur.moyenDeStockage()} · persistance ${Navigateur.persistanceActuelle()} · ${Navigateur.estimation()}",
        "Écran allumé (Wake Lock)" to etatEcranAllume(appareil),
        "Taille de la page (Resource Timing)" to Navigateur.tailleTransferee(),
        "Temps jusqu'à la première image" to (ouverture?.let { "${it.toLong()} ms" } ?: "pas encore mesuré") +
            Ouverture.precedente.let { if (it.isEmpty()) "" else " (ouverture précédente : $it ms)" },
    )
}

/** Le rapport de maintenant : environnement, étapes de la session (par défaut), verdicts donnés, relevé, chargements. */
suspend fun rapportCourant(
    etapes: List<ResultatEtape> = Banc.resultats.toList(),
    verdicts: List<VerdictGrille> = emptyList(),
): Rapport {
    val brut = environnementBrut()
    return Rapport(
        build = Navigateur.build(),
        version = Navigateur.version,
        date = Navigateur.dateLocale(),
        testeur = Navigateur.lireReglage(Banc.REGLAGE_TESTEUR),
        iosIndique = Navigateur.lireReglage(Banc.REGLAGE_IOS),
        remarque = Navigateur.lireReglage(Banc.REGLAGE_REMARQUE),
        appareil = appareilCourant(brut),
        environnement = environnementDuRapport(brut),
        etapes = etapes,
        verdicts = verdicts,
        releve = Navigateur.releveLire().lines().filter { it.isNotBlank() },
        chargements = Navigateur.chargements().lines().filter { it.isNotBlank() },
    )
}

/**
 * L'export d'un rapport. `copier` et `partager` doivent partir du geste du toucher
 * (iOS refuse sinon) : leur passer un rapport DÉJÀ construit, sans suspension avant.
 */
object ExportRapport {
    /** Le statut se lit ensuite dans `Navigateur.statutCopie()`. */
    fun copier(rapport: Rapport) = Navigateur.copierTexte(rapport.enTexte())

    /** Rend une phrase : ce qui a été partagé, ou pourquoi pas. */
    suspend fun partager(rapport: Rapport): String {
        val r = Navigateur.partager(rapport.titre(), rapport.enTexte(), rapport.enJson())
        return r.substring(1).replaceFirstChar { it.uppercase() } + "."
    }

    /** Ouvre un ticket par la fonction Edge `signaler` ; l'URL du ticket, ou la raison de l'échec. */
    suspend fun envoyer(rapport: Rapport): ResultatEnvoi {
        if (!Navigateur.envoiDisponible()) return lireResultatEnvoi("Econfig|")
        val s = rapport.pourSignaler()
        return lireResultatEnvoi(Navigateur.envoyerRapport(s.titre, s.description, s.contexte, s.journal))
    }
}
