package com.example.lebiais.sonde

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.booleanOrNull
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive

// Les verdicts du parcours automatique, un par point de la grille
// (plans/2026-11-05-pwa-ios-etape-0-grille.md) : logique pure. Chaque verdict est « passé »,
// « échoué » ou « à voir à la main », avec une phrase de raison.

const val PASSE = "passé"
const val ECHOUE = "échoué"
const val A_VOIR = "à voir à la main"

// Seuils de la grille et du plan (plans/2026-11-05-pwa-ios-etape-0.md).
const val SEUIL_STOCKAGE_MO = 50
const val SEUIL_STOCKAGE_JOURS = 8
const val SEUIL_OUVERTURE_MS = 5000
const val BETES_DE_LA_LISTE = 300
const val ENDURANCE_GRILLE_MIN = 20
const val SEUIL_FPS = 30
const val SEUIL_PAUSE_LISTE_MS = 2000
const val SEUIL_REMPLISSAGE_MS = 3000
const val SEUIL_REFUSEES_POURCENT = 5
const val SEUIL_PAUSE_ENDURANCE_MS = 5000
/** Une marge sûre au-delà est invraisemblable (px CSS) : l'encoche la plus haute fait ~60 px. */
const val MARGE_PLAUSIBLE_MAX_PX = 100

/** Les questions rapides de fin de parcours. */
enum class Question(val libelle: String) {
    ACCENTS("Les accents (é è ê à ç ô î ù œ) s'écrivent-ils correctement ?"),
    MAJUSCULE("Le champ « Nom » commence-t-il de lui-même par une majuscule ?"),
    CORRECTION("La correction automatique propose-t-elle ou corrige-t-elle des mots ?"),
    COPIER_COLLER("Pouvez-vous copier un mot puis le coller dans un autre champ ?"),
    DICTEE("La dictée (le micro du clavier) est-elle proposée et écrit-elle ?"),
    POLICE("Le texte est-il net, accents compris, dans tous les écrans ?"),
    HORS_LIGNE("En mode avion, la sonde s'ouvre-t-elle depuis son icône ?"),
}

enum class Reponse(val libelle: String) { OUI("Oui"), NON("Non"), NE_SAIT_PAS("Je ne sais pas") }

/** Les questions de saisie (point 1). */
val QUESTIONS_SAISIE = listOf(Question.ACCENTS, Question.MAJUSCULE, Question.CORRECTION, Question.COPIER_COLLER, Question.DICTEE)

private val NOMS_COURTS = mapOf(
    Question.ACCENTS to "accents", Question.MAJUSCULE to "majuscule automatique", Question.CORRECTION to "correction automatique",
    Question.COPIER_COLLER to "copier-coller", Question.DICTEE to "dictée",
)

fun verdictSaisie(reponses: Map<Question, Reponse>, clavier: MesureClavier?): VerdictGrille {
    val intitule = "Saisie (accents, majuscule, correction, copier-coller, dictée, dernier champ)"
    val non = QUESTIONS_SAISIE.filter { reponses[it] == Reponse.NON }.map { NOMS_COURTS.getValue(it) }
    val inconnues = QUESTIONS_SAISIE.filter { reponses[it] == null || reponses[it] == Reponse.NE_SAIT_PAS }.map { NOMS_COURTS.getValue(it) }
    val clavierTexte = when {
        clavier == null -> "dernier champ : non mesuré (toucher le dernier champ de l'écran Saisie)"
        clavier.clavierPx <= 0 -> "dernier champ : aucun clavier à l'écran pendant la mesure (${clavier.enTexte()})"
        else -> "dernier champ au-dessus du clavier : ${clavier.enTexte()}"
    }
    val clavierCache = clavier != null && clavier.clavierPx > 0 && !clavier.visible
    val clavierInconnu = clavier == null || clavier.clavierPx <= 0
    return when {
        non.isNotEmpty() || clavierCache -> VerdictGrille(
            "1", intitule, ECHOUE,
            (if (non.isNotEmpty()) "ne marche pas : ${non.joinToString(", ")} ; " else "") +
                (if (clavierCache) "le champ touché finit sous le clavier ; " else "") + clavierTexte,
        )
        inconnues.isNotEmpty() || clavierInconnu -> VerdictGrille(
            "1", intitule, A_VOIR,
            (if (inconnues.isNotEmpty()) "sans réponse sûre : ${inconnues.joinToString(", ")} ; " else "réponses : tout marche ; ") + clavierTexte,
        )
        else -> VerdictGrille("1", intitule, PASSE, "tout marche d'après le testeur ; $clavierTexte")
    }
}

fun verdictZonesSures(marges: List<String>, margeMaxPx: Int, autonome: Boolean): VerdictGrille {
    val intitule = "Zones sûres"
    val lues = if (marges.isEmpty()) "aucune marge relevée" else "marges lues : ${marges.joinToString(" ; ")}"
    val mode = if (autonome) "" else " (ouverte dans un onglet : les marges de l'app d'écran d'accueil peuvent différer)"
    if (margeMaxPx > MARGE_PLAUSIBLE_MAX_PX) {
        return VerdictGrille("2", intitule, ECHOUE, "marge de $margeMaxPx px, invraisemblable (> $MARGE_PLAUSIBLE_MAX_PX px) ; $lues$mode")
    }
    return VerdictGrille(
        "2", intitule, A_VOIR,
        "$lues$mode ; à regarder à l'œil : rien sous l'encoche ni la barre d'accueil, en portrait puis en paysage",
    )
}

fun verdictPolice(reponse: Reponse?): VerdictGrille = when (reponse) {
    Reponse.OUI -> VerdictGrille("3", "Police", PASSE, "texte net, accents compris, d'après le testeur")
    Reponse.NON -> VerdictGrille("3", "Police", ECHOUE, "texte flou ou accents mal dessinés, d'après le testeur")
    else -> VerdictGrille("3", "Police", A_VOIR, "comparer avec une capture de l'application Android (TeX Gyre Heros, accents)")
}

fun verdictStockage(d: DonneesParcours): VerdictGrille {
    val intitule = "Stockage ($SEUIL_STOCKAGE_MO Mo, persistance, J+$SEUIL_STOCKAGE_JOURS)"
    val ancienne = when {
        d.ancienneAgeJours == null || d.ancienneIntacte == null -> null
        else -> "écriture précédente du ${d.ancienneEcriture.ifBlank { "?" }} (${d.ancienneAgeJours} jours) relue : " +
            if (d.ancienneIntacte) "intacte" else "FAUSSE ou perdue"
    }
    val j8 = when {
        d.ancienneIntacte == true && (d.ancienneAgeJours ?: 0) >= SEUIL_STOCKAGE_JOURS -> "J+$SEUIL_STOCKAGE_JOURS vérifié ($ancienne)"
        ancienne != null -> "$ancienne ; J+$SEUIL_STOCKAGE_JOURS : relancer un parcours dans $SEUIL_STOCKAGE_JOURS jours sans rien effacer"
        else -> "J+$SEUIL_STOCKAGE_JOURS : relancer un parcours dans $SEUIL_STOCKAGE_JOURS jours sans rien effacer"
    }
    val estimation = if (d.estimation.isNotBlank()) " ; estimation : ${d.estimation}" else ""
    return when {
        d.ecritureOk == null -> VerdictGrille("4", intitule, A_VOIR, "étape Stockage non faite ; $j8")
        d.ecritureOk == false -> VerdictGrille("4", intitule, ECHOUE, "écriture de $SEUIL_STOCKAGE_MO Mo refusée : ${d.ecritureDetail}")
        d.relectureIntacte == null -> VerdictGrille("4", intitule, A_VOIR, "$SEUIL_STOCKAGE_MO Mo écrits ; relecture non faite (parcours arrêté avant) ; $j8")
        d.relectureIntacte == false -> VerdictGrille("4", intitule, ECHOUE, "relecture : ${d.relectureDetail.ifBlank { "pas intacte" }}")
        d.ancienneIntacte == false -> VerdictGrille("4", intitule, ECHOUE, "$SEUIL_STOCKAGE_MO Mo écrits et relus intacts, mais $ancienne")
        d.persistance != "accordée" -> VerdictGrille(
            "4", intitule, A_VOIR,
            "$SEUIL_STOCKAGE_MO Mo écrits et relus intacts ; stockage persistant ${d.persistance.ifBlank { "non demandé" }} : à revoir à J+$SEUIL_STOCKAGE_JOURS$estimation ; $j8",
        )
        else -> VerdictGrille("4", intitule, PASSE, "$SEUIL_STOCKAGE_MO Mo écrits et relus intacts, persistance accordée$estimation ; $j8")
    }
}

fun verdictHorsLigne(horsLigne: OuvertureHorsLigne?, reponse: Reponse?): VerdictGrille {
    val intitule = "Hors ligne (mode avion, ouverture depuis l'icône)"
    return when {
        horsLigne != null -> VerdictGrille("5", intitule, PASSE, "ouverture hors ligne vue par la sonde le ${horsLigne.date} en ${horsLigne.ms} ms (chargement n° ${horsLigne.chargement})")
        reponse == Reponse.OUI -> VerdictGrille("5", intitule, PASSE, "s'ouvre en mode avion, d'après le testeur")
        reponse == Reponse.NON -> VerdictGrille("5", intitule, ECHOUE, "ne s'ouvre pas en mode avion, d'après le testeur")
        else -> VerdictGrille("5", intitule, A_VOIR, "mode avion, fermer la sonde, l'ouvrir depuis l'icône : la sonde note seule l'ouverture hors ligne")
    }
}

fun verdictPrecache(json: String): VerdictGrille {
    val intitule = "Précache complet (condition du hors ligne)"
    val objet = try {
        Json.parseToJsonElement(json).jsonObject
    } catch (e: Exception) {
        return VerdictGrille("5", intitule, A_VOIR, "contrôle du précache illisible ou absent")
    }
    objet["etat"]?.let { return VerdictGrille("5", intitule, A_VOIR, "contrôle impossible : ${it.jsonPrimitive.content}") }
    val requis = objet["requis"]?.jsonArray?.map { it.jsonArray[0].jsonPrimitive.content to (it.jsonArray[1].jsonPrimitive.booleanOrNull == true) }
        ?: return VerdictGrille("5", intitule, A_VOIR, "contrôle du précache sans liste de fichiers")
    val manquants = requis.filter { !it.second }.map { it.first }
    return if (manquants.isEmpty()) VerdictGrille("5", intitule, PASSE, "${requis.size}/${requis.size} fichiers requis en cache")
    else VerdictGrille("5", intitule, ECHOUE, "${requis.size - manquants.size}/${requis.size} requis en cache ; manquent : ${manquants.joinToString(", ")}")
}

fun verdictFluiditeListe(mesure: FluiditeMesuree?, betesVues: Int): VerdictGrille {
    val intitule = "Fluidité — liste de $BETES_DE_LA_LISTE bêtes (défilement automatique)"
    if (mesure == null || mesure.secondes == 0) return VerdictGrille("6", intitule, A_VOIR, "pas de mesure (étape non faite)")
    val texte = "${mesure.enTexte()} ; $betesVues bêtes parcourues"
    return when {
        mesure.moyenne < SEUIL_FPS -> VerdictGrille("6", intitule, ECHOUE, "moins de $SEUIL_FPS i/s en moyenne : $texte")
        mesure.pauseMaxMs >= SEUIL_PAUSE_LISTE_MS -> VerdictGrille("6", intitule, ECHOUE, "une pause d'au moins ${SEUIL_PAUSE_LISTE_MS / 1000} s : $texte")
        betesVues < BETES_DE_LA_LISTE -> VerdictGrille("6", intitule, A_VOIR, "le défilement n'a pas atteint le bas de la liste : $texte")
        else -> VerdictGrille("6", intitule, PASSE, "$texte (images par seconde d'un défilement piloté, pas la réponse au doigt)")
    }
}

fun verdictFluiditeCarte(mesure: FluiditeMesuree?, remplissage: Remplissage, recues: Int, refusees: Int): VerdictGrille {
    val intitule = "Fluidité — carte (trajet scripté, remplissage des tuiles)"
    if (mesure == null || mesure.secondes == 0) return VerdictGrille("6", intitule, A_VOIR, "pas de mesure (étape non faite)")
    val total = recues + refusees
    val pourcent = if (total == 0) 0 else refusees * 100 / total
    val texte = "${mesure.enTexte()} ; remplissage ${remplissage.enTexte()} ; tuiles $recues reçues / $refusees refusées ($pourcent %)"
    val raisons = buildList {
        if (mesure.moyenne < SEUIL_FPS) add("moins de $SEUIL_FPS i/s en moyenne")
        if (remplissage.medianeMs == null) add("aucun remplissage complet")
        else if (remplissage.medianeMs >= SEUIL_REMPLISSAGE_MS) add("remplissage médian d'au moins ${SEUIL_REMPLISSAGE_MS / 1000} s")
        if (total == 0) add("aucune tuile reçue")
        else if (pourcent >= SEUIL_REFUSEES_POURCENT) add("$pourcent % de tuiles refusées (seuil $SEUIL_REFUSEES_POURCENT %)")
    }
    return if (raisons.isEmpty()) VerdictGrille("6", intitule, PASSE, texte)
    else VerdictGrille("6", intitule, ECHOUE, raisons.joinToString(", ") + " : " + texte)
}

fun verdictTelechargement(tailleTransferee: String, premiereImageMs: Double?): VerdictGrille {
    val intitule = "Premier téléchargement"
    if (tailleTransferee.isBlank() || premiereImageMs == null) {
        return VerdictGrille("7", intitule, A_VOIR, "pas de mesure ; à relever dans l'inspecteur Web de Safari")
    }
    return VerdictGrille(
        "7", intitule, PASSE,
        "mesuré (la grille demande seulement de noter) : $tailleTransferee ; première image à ${premiereImageMs.toLong()} ms ; à refaire en 4G puis en Wi-Fi, cache vidé",
    )
}

fun verdictOuverture(ouvertureMs: Double?, horsLigne: OuvertureHorsLigne?): VerdictGrille {
    val intitule = "Ouverture déjà en cache (< ${SEUIL_OUVERTURE_MS / 1000} s)"
    val (ms, comment) = when {
        horsLigne != null -> horsLigne.ms.toDouble() to "ouverture hors ligne du ${horsLigne.date}"
        ouvertureMs != null -> ouvertureMs to "ouverture mesurée au lancement du parcours, en ligne (hors ligne pas encore vue)"
        else -> return VerdictGrille("8", intitule, A_VOIR, "temps d'ouverture non mesuré")
    }
    return if (ms < SEUIL_OUVERTURE_MS) VerdictGrille("8", intitule, PASSE, "${ms.toLong()} ms, $comment")
    else VerdictGrille("8", intitule, ECHOUE, "${ms.toLong()} ms, $comment")
}

fun verdictFluiditeComparee(): VerdictGrille =
    VerdictGrille("9", "Fluidité comparée iPad / iPhone", A_VOIR, "comparer les rapports des deux appareils (mêmes étapes, mêmes mesures)")

fun verdictEndurance(enduranceS: Int, pauseMaxMs: Int?, chargementAvant: Int, chargementApres: Int, arrete: Boolean): VerdictGrille {
    val intitule = "Endurance ($ENDURANCE_GRILLE_MIN min)"
    val minutes = enduranceS / 60
    val recharge = if (chargementApres != chargementAvant)
        " ; la page a été rechargée (chargement n° $chargementAvant puis n° $chargementApres) : information, iOS décharge les pages sous pression mémoire (lecture retenue du 21/11)"
    else ""
    if (pauseMaxMs == null || enduranceS == 0) {
        return VerdictGrille("10", intitule, A_VOIR, (if (arrete) "parcours arrêté avant l'endurance" else "endurance non faite") + recharge)
    }
    val texte = "$minutes min ${enduranceS % 60} s d'endurance, pause max $pauseMaxMs ms"
    return when {
        pauseMaxMs >= SEUIL_PAUSE_ENDURANCE_MS -> VerdictGrille("10", intitule, ECHOUE, "une pause d'au moins ${SEUIL_PAUSE_ENDURANCE_MS / 1000} s : $texte$recharge")
        minutes < ENDURANCE_GRILLE_MIN -> VerdictGrille("10", intitule, A_VOIR, "aucune pause d'au moins ${SEUIL_PAUSE_ENDURANCE_MS / 1000} s ($texte) ; la grille demande $ENDURANCE_GRILLE_MIN min : relancer le parcours de 20 min$recharge")
        else -> VerdictGrille("10", intitule, PASSE, "aucune pause d'au moins ${SEUIL_PAUSE_ENDURANCE_MS / 1000} s : $texte$recharge")
    }
}

fun verdictFichesPhotos(d: DonneesParcours): VerdictGrille {
    val intitule = "Fiches et photos en mémoire (charge de l'endurance)"
    if (d.fichesVoulues == 0 && d.photosVoulues == 0) return VerdictGrille("10", intitule, A_VOIR, "étapes Fiches et Photos non faites")
    val texte = "${d.fichesCreees}/${d.fichesVoulues} fiches, ${d.photosFaites}/${d.photosVoulues} photos de 12 Mpx, mémoire décodée maximale ${d.decodesMaxMo} Mo" +
        if (d.photosArret.isNotBlank()) " ; série : ${d.photosArret}" else ""
    return when {
        d.fichesErreur.isNotBlank() -> VerdictGrille("10", intitule, ECHOUE, "fiches : ${d.fichesErreur} ; $texte")
        d.photosArret.startsWith("fabrication impossible") -> VerdictGrille("10", intitule, ECHOUE, texte)
        else -> VerdictGrille("10", intitule, PASSE, "créées sans erreur : $texte")
    }
}

/** Tous les verdicts du parcours, dans l'ordre de la grille. */
fun verdictsDuParcours(av: Avancement, chargementCourant: Int, horsLigne: OuvertureHorsLigne?): List<VerdictGrille> {
    val d = av.donnees
    val reponses = d.reponsesLues()
    return listOf(
        verdictSaisie(reponses, d.clavier),
        verdictZonesSures(d.marges, d.margeMaxPx, av.installation == "autonome"),
        verdictPolice(reponses[Question.POLICE]),
        verdictStockage(d),
        verdictHorsLigne(horsLigne, reponses[Question.HORS_LIGNE]),
        verdictPrecache(d.precacheJson),
        verdictFluiditeListe(d.liste, d.listeBetesVues),
        verdictFluiditeCarte(d.carte, resumeRemplissage(d.remplissagesMs), d.tuilesRecues, d.tuilesRefusees),
        verdictTelechargement(d.tailleTransferee, d.ouvertureMs),
        verdictOuverture(d.ouvertureMs, horsLigne),
        verdictFluiditeComparee(),
        verdictEndurance(d.enduranceS, d.endurancePauseMaxMs, av.chargementAuDebut, chargementCourant, av.etat == PARCOURS_ARRETE),
        verdictFichesPhotos(d),
    )
}

/** « 9 passés · 2 échoués · 4 à voir à la main ». */
fun resumeVerdicts(verdicts: List<VerdictGrille>): String {
    val passes = verdicts.count { it.verdict == PASSE }
    val echoues = verdicts.count { it.verdict == ECHOUE }
    val aVoir = verdicts.count { it.verdict == A_VOIR }
    return "$passes passé${if (passes > 1) "s" else ""} · $echoues échoué${if (echoues > 1) "s" else ""} · $aVoir $A_VOIR"
}
