/** Une photo gardée en mémoire : son image décodée, ou rien si Skia ne l'a pas lue. */
private class PhotoGardee(val image: ImageBitmap?, val typeMime: String, val octets: Int, val raison: String = "") {
    /** Ce que pèse l'image décodée en mémoire (0 si elle n'est pas lue). */
    val octetsDecodes: Long = image?.let { octetsDecodes(it.width, it.height) } ?: 0L
}

// Gardées pour toute la vie de la page, pas pour celle de l'écran : revenir au menu ne les efface pas.
// Seul un rechargement de la page les vide, ce que l'essai d'endurance veut voir.
private val photosEnMemoire = mutableStateListOf<PhotoGardee>()

internal fun nombrePhotos(): Int = photosEnMemoire.size
internal fun octetsDecodesPhotos(): Long = photosEnMemoire.sumOf { it.octetsDecodes }
internal fun viderPhotos() = photosEnMemoire.clear()

/**
 * La mémoire d'une image décodée : 4 octets (RGBA) par pixel. C'est elle, pas le
 * fichier JPEG compressé, qui décide si l'appareil tient quand on garde des dizaines de photos.
 */
internal fun octetsDecodes(largeur: Int, hauteur: Int): Long = largeur.toLong() * hauteur * 4

/** Compte les images dessinées pendant [ms] (au moins une), en images par seconde. */
private suspend fun imagesParSecondePendant(ms: Double): Int {
    val debut = Navigateur.msDepuisLancement()
    var images = 0
    while (true) {
        withFrameNanos { }
        val ecoule = Navigateur.msDepuisLancement() - debut
        images++
        if (ecoule >= ms) return (images * 1000 / ecoule).toInt()
    }
}

/** Les tailles proposées aux photos synthétiques : 12 Mpx (un appareil photo d'iPhone) d'abord. */
val TAILLES_SYNTHETIQUES = listOf(4000 to 3000, 2000 to 1500, 1000 to 750)

private var graineDesPhotos = 1

/**
 * Fabrique [n] photos JPEG synthétiques dans un canevas (sonde.js) et les fait passer par le même
 * chemin que les vraies : octets → `Navigateur.decoderImage` → liste en mémoire. Mesure la fabrication
 * et le décodage de chaque photo ; rend la main entre deux photos. S'arrête si le garde-fou le dit
 * (moins de 10 i/s plus de 3 s, ou plus de 800 Mo décodés). [progres] reçoit une phrase après chaque photo.
 * Écrit un événement dans le relevé et une étape dans le banc. Appelée aussi par le parcours (lot B) ;
 * [noter] faux : ni événement ni étape (les petits ajouts répétés de l'endurance).
 */
suspend fun seriePhotosSynthetiques(
    n: Int,
    largeur: Int = TAILLES_SYNTHETIQUES[0].first,
    hauteur: Int = TAILLES_SYNTHETIQUES[0].second,
    noter: Boolean = true,
    progres: (String) -> Unit = {},
): ResultatEtape {
    val gardeFou = GardeFou()
    val debut = Navigateur.msDepuisLancement()
    var faites = 0
    var fabrication = 0.0
    var decodage = 0.0
    var jpeg = 0L
    var nonDecodees = 0
    var premiereRaison = ""
    var arret: String? = null
    // Le garde-fou regarde les images par seconde PENDANT LA PAUSE entre deux photos : une photo de
    // 12 Mpx bloque l'écran plus d'une seconde, ce qui est mesuré à part ; ce qui compte, c'est que
    // l'interface reprenne entre deux. Avant la première photo : la valeur du bandeau.
    var fpsAuRepos = Fluidite.fps
    for (i in 1..n) {
        arret = gardeFou.verifier(Navigateur.msDepuisLancement(), fpsAuRepos, octetsDecodesPhotos())
        if (arret != null) break
        val t0 = Navigateur.msDepuisLancement()
        val reponse = Navigateur.photoSynthetique(largeur, hauteur, graineDesPhotos++)
        val octets = if (reponse.startsWith("O")) octetsDepuisBase64(reponse.substring(1)) else null
        if (octets == null) {
            arret = "fabrication impossible : " + reponse.removePrefix("E").ifEmpty { "JPEG vide" }
            break
        }
        val t1 = Navigateur.msDepuisLancement()
        val image = Navigateur.decoderImage(octets)
        val t2 = Navigateur.msDepuisLancement()
        var raison = ""
        if (image == null) {
            nonDecodees++
            // Séparer un JPEG abîmé d'un décodeur sans mémoire : le navigateur relit le même fichier.
            val natif = Navigateur.dernierePhotoLisible()
            raison = Navigateur.raisonDernierDecodage().ifEmpty { "décodeur sans erreur nommée" } + " · " + natif
            if (premiereRaison.isEmpty()) premiereRaison = raison
        }
        photosEnMemoire.add(PhotoGardee(image, "image/jpeg (synthétique)", octets.size, raison))
        faites++
        val arretDecodage = gardeFou.noterDecodage(image != null, octetsDecodesPhotos())
        fabrication += t1 - t0
        decodage += t2 - t1
        jpeg += octets.size
        progres("photo $i/$n : fabrication ${(t1 - t0).toLong()} ms, décodage ${(t2 - t1).toLong()} ms, ${mo(octets.size.toLong())} Mo en JPEG · ${mo(octetsDecodesPhotos())} Mo décodés en mémoire")
        if (arretDecodage != null) { arret = arretDecodage; break }
        // Rendre la main une demi-seconde : l'écran se redessine, et l'on compte ses images.
        fpsAuRepos = imagesParSecondePendant(500.0)
    }
    val duree = Navigateur.msDepuisLancement() - debut
    val verdict = if (arret == null) "fini ($faites/$n)" else "arrêtée à $faites/$n : $arret"
    val resultat = ResultatEtape(
        "$n photos synthétiques ${largeur}×$hauteur", verdict,
        listOf(
            "fabrication moyenne (canevas + JPEG)" to if (faites > 0) "${(fabrication / faites).toLong()} ms" else "—",
            "décodage moyen (Skia)" to if (faites > 0) "${(decodage / faites).toLong()} ms" else "—",
            "JPEG moyen" to if (faites > 0) "${mo(jpeg / faites)} Mo" else "—",
            "non décodées" to "$nonDecodees",
            "raison du premier échec de décodage" to premiereRaison.ifEmpty { "—" },
            "photos en mémoire" to "${photosEnMemoire.size}",
            "décodé en mémoire" to "${mo(octetsDecodesPhotos())} Mo",
            "durée totale" to "${(duree / 1000).toLong()} s",
        ),
    )
    if (noter) {
        Banc.evenement("${resultat.nom} : $verdict · décodage moyen ${resultat.mesures[1].second} · ${mo(octetsDecodesPhotos())} Mo décodés")
        Banc.noterEtape(resultat)
    }
    return resultat
}

@Composable
fun EcranPhotos() {
    val photos = photosEnMemoire
    val scope = rememberCoroutineScope()
    val compresses = photos.sumOf { it.octets.toLong() }
    val decodes = photos.sumOf { it.octetsDecodes }

    Column(Modifier.fillMaxSize().padding(16.dp)) {
        // UNDISPATCHED : la coroutine démarre tout de suite, dans le clic, et ouvre le sélecteur
        // avant sa première suspension. Une coroutine lancée « plus tard » perdrait le geste de l'utilisateur (iOS).
        fun ajouter(capture: Boolean) = scope.launch(start = CoroutineStart.UNDISPATCHED) {
            val choisie = Navigateur.choisirPhoto(capture) ?: return@launch
            photos.add(PhotoGardee(Navigateur.decoderImage(choisie.octets), choisie.typeMime, choisie.octets.size))
        }
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            Button(onClick = { ajouter(true) }) { Text("Prendre une photo") }
            Button(onClick = { ajouter(false) }) { Text("Choisir une photo") }
        }
        // Séries de photos synthétiques : même chemin que les vraies, sans sélecteur à toucher.
        var taille by remember { mutableStateOf(0) }
        var enCours by remember { mutableStateOf(false) }
        var etat by remember { mutableStateOf("") }
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            for (n in listOf(10, 30)) {
                OutlinedButton(
                    enabled = !enCours,
                    onClick = {
                        enCours = true
                        val (l, h) = TAILLES_SYNTHETIQUES[taille]
                        scope.launch {
                            try {
                                val r = seriePhotosSynthetiques(n, l, h) { etat = it }
                                etat = "${r.nom} : ${r.verdict} · " + r.mesures.joinToString(" · ") { "${it.first} ${it.second}" }
                            } finally { enCours = false }
                        }
                    },
                ) { Text("$n photos synthétiques") }
            }
        }
        val (largeurChoisie, hauteurChoisie) = TAILLES_SYNTHETIQUES[taille]
        Text(
            "Taille : ${largeurChoisie}×$hauteurChoisie (${(largeurChoisie.toLong() * hauteurChoisie / 100_000).let { "${it / 10},${it % 10}" }} Mpx), toucher pour changer",
            fontSize = 13.sp,
            color = Color(0xFF1F1B16),
            modifier = Modifier.clickable(enabled = !enCours) { taille = (taille + 1) % TAILLES_SYNTHETIQUES.size }.padding(vertical = 6.dp),
        )
        if (etat.isNotEmpty()) Text(etat, fontSize = 13.sp, color = Color(0xFF7A6F60), modifier = Modifier.padding(top = 4.dp))
        Text(
            "${photos.size} photos · ${mo(compresses)} Mo compressés · ≈ ${mo(decodes)} Mo décodés en mémoire",
            fontSize = 14.sp,
            color = Color(0xFF1F1B16),
            modifier = Modifier.padding(vertical = 8.dp),
        )
        LazyVerticalGrid(GridCells.Adaptive(120.dp), Modifier.fillMaxSize()) {
            items(photos) { p ->
                Box(
                    Modifier.padding(2.dp).fillMaxWidth().aspectRatio(1f).background(Color(0xFFE8E0D0)),
                    contentAlignment = Alignment.Center,
                ) {
                    if (p.image != null) {
                        Image(p.image, null, Modifier.fillMaxSize(), contentScale = ContentScale.Crop)
                    } else {
                        Text(if (p.raison.isNotEmpty()) "non décodée : ${p.raison}" else "format non lu : ${p.typeMime.ifEmpty { "type inconnu" }}", fontSize = 11.sp, color = Color(0xFFB3261E), modifier = Modifier.padding(6.dp))
                    }
                }
            }
        }
    }
}
