// L'écran « Parcours automatique » (lot B), en tête du menu : accueil (consigne, réglages, durée,
// Lancer), parcours en cours (bandeau + écran piloté), questions rapides, fin (verdicts et envoi).

private val ENCRE = Color(0xFF1F1B16)
private val ENCADRE = Color(0xFFF0E6CF)
private val ALERTE = Color(0xFFFCE8E6)
private val ROUGE = Color(0xFFB3261E)
private val VERT = Color(0xFF2E6B3A)
private val GRIS = Color(0xFF7A6F60)

/** Le scope de la racine : le parcours y tourne, pour survivre aux écrans et garder l'horloge d'images de Compose. */
val LocalScopeRacine = staticCompositionLocalOf<CoroutineScope?> { null }

private fun mmss(secondes: Int): String = "${secondes / 60}:${(secondes % 60).toString().padStart(2, '0')}"

@Composable
fun EcranParcours() {
    when (MoteurParcours.phase) {
        Phase.ACCUEIL -> AccueilParcours()
        Phase.EN_COURS -> ParcoursEnCours()
        Phase.QUESTIONS -> QuestionsRapides()
        Phase.FIN -> FinDuParcours()
    }
}

@Composable
private fun AccueilParcours() {
    val scope = rememberCoroutineScope()
    val racine = LocalScopeRacine.current
    val appareil = remember { appareilCourant() }
    val garde = remember { avancementGarde() }
    val coupure = remember { interruption(garde, Navigateur.numeroChargement()) }
    var installation by remember { mutableStateOf(Navigateur.etatInstallation()) }
    var duree by remember { mutableStateOf(Navigateur.lireReglage(REGLAGE_DUREE).toIntOrNull()?.takeIf { it in DUREES_PARCOURS } ?: 10) }
    var testeur by remember { mutableStateOf(Navigateur.lireReglage(Banc.REGLAGE_TESTEUR)) }
    var ios by remember { mutableStateOf(Navigateur.lireReglage(Banc.REGLAGE_IOS)) }
    var lancement by remember { mutableStateOf(false) }
    val horsLigne = remember { ouvertureHorsLigneNotee() }
    LaunchedEffect(Unit) {
        while (true) {
            installation = Navigateur.etatInstallation()
            delay(2000)
        }
    }

    Column(
        Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(12.dp),
    ) {
        if (coupure != null && garde != null) {
            Column(Modifier.fillMaxWidth().background(ALERTE).padding(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                Text(coupure.message(), color = ENCRE, fontSize = 15.sp)
                Text("Ce n'est pas forcément un échec : iOS décharge les pages quand la mémoire manque. Le rechargement est noté dans le rapport.", color = ENCRE, fontSize = 13.sp)
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    Button(onClick = { MoteurParcours.voir(garde) }) { Text("Voir le rapport partiel") }
                    OutlinedButton(onClick = { MoteurParcours.recommencer() }) { Text("Recommencer") }
                }
            }
        } else if (garde != null && garde.etat != PARCOURS_EN_COURS) {
            Text(
                "Dernier parcours : ${garde.plan.dureeMin} min, lancé le ${garde.dateDebut} (${garde.etat}). Voir son rapport ›",
                color = ENCRE, fontSize = 14.sp,
                modifier = Modifier.fillMaxWidth().background(ENCADRE).clickable { MoteurParcours.voir(garde) }.padding(12.dp),
            )
        }
        if (horsLigne != null) {
            Text("Ouverture hors ligne notée le ${horsLigne.date} : ${horsLigne.ms} ms.", color = VERT, fontSize = 14.sp)
        }

        Text("Parcours automatique", color = ENCRE, fontSize = 20.sp, fontWeight = FontWeight.Bold)
        Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
            Text("1. Gardez l'écran allumé et restez dans la sonde jusqu'à la fin (ne passez pas à une autre application).", color = ENCRE, fontSize = 15.sp)
            Text("2. Ne touchez pas l'écran pendant le parcours : la sonde fait défiler, glisse et zoome seule.", color = ENCRE, fontSize = 15.sp)
            Text("3. Elle mesure le stockage (50 Mo), la fluidité de la liste et de la carte, les fiches et photos en mémoire, l'endurance.", color = ENCRE, fontSize = 15.sp)
            Text("4. À la fin : quelques questions rapides, puis un rapport à envoyer d'un toucher.", color = ENCRE, fontSize = 15.sp)
        }
        if (installation != "autonome") {
            Text(
                "Attention : la sonde n'est pas ouverte depuis son icône d'écran d'accueil. Le parcours marche quand même, " +
                    "mais les mesures (stockage, marges, hors ligne) valent pour l'onglet, pas pour l'app installée. " +
                    "Pour installer : bouton « Installer » en haut.",
                color = ENCRE, fontSize = 13.sp,
                modifier = Modifier.fillMaxWidth().background(ALERTE).padding(10.dp),
            )
        }
        OutlinedTextField(
            value = ios,
            onValueChange = { ios = it; Navigateur.ecrireReglage(Banc.REGLAGE_IOS, it) },
            label = { Text("Version d'iOS (Réglages › Général › Informations)") },
            singleLine = true,
            modifier = Modifier.fillMaxWidth().modeClavierAuToucher("text", "none").onFocusChanged { if (it.isFocused) Navigateur.modeClavier("text", "none") },
        )
        OutlinedTextField(
            value = testeur,
            onValueChange = { testeur = it; Navigateur.ecrireReglage(Banc.REGLAGE_TESTEUR, it) },
            label = { Text("Testeur / appareil (facultatif)") },
            singleLine = true,
            modifier = Modifier.fillMaxWidth().modeClavierAuToucher("text", "words").onFocusChanged { if (it.isFocused) Navigateur.modeClavier("text", "words") },
        )
        Text("Durée", color = ENCRE, fontSize = 15.sp)
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
            for (d in DUREES_PARCOURS) {
                val choisir = { duree = d; Navigateur.ecrireReglage(REGLAGE_DUREE, d.toString()) }
                if (d == duree) Button(onClick = choisir, modifier = Modifier.weight(1f).height(52.dp)) { Text("$d min", fontSize = 16.sp) }
                else OutlinedButton(onClick = choisir, modifier = Modifier.weight(1f).height(52.dp)) { Text("$d min", fontSize = 16.sp) }
            }
        }
        Text(
            when (duree) {
                3 -> "3 min : un aperçu, chaque étape en version courte."
                10 -> "10 min : toutes les étapes, environ 6 min d'endurance."
                else -> "20 min : l'essai complet de la grille, environ 16 min d'endurance."
            },
            color = GRIS, fontSize = 13.sp,
        )
        Button(
            enabled = !lancement && racine != null,
            onClick = {
                lancement = true
                // UNDISPATCHED : Wake Lock est demandé dans le geste du toucher (iOS le refuse sinon).
                scope.launch(start = CoroutineStart.UNDISPATCHED) {
                    try {
                        Navigateur.ecranAllumeDemander()
                        MoteurParcours.lancer(racine!!, duree, etatEcranAllume(appareil), installation)
                    } finally { lancement = false }
                }
            },
            modifier = Modifier.fillMaxWidth().height(60.dp),
        ) { Text("Lancer", fontSize = 18.sp) }
        Text(
            "Ce que le parcours ne mesure pas : il anime la liste et la carte par programme, il mesure donc les images par seconde, pas la réponse à un vrai doigt ni la saisie au clavier (les questions de fin s'en chargent).",
            color = GRIS, fontSize = 12.sp,
        )
    }
}

@Composable
private fun ParcoursEnCours() {
    val av = MoteurParcours.avancement
    var ecoule by remember { mutableStateOf(0) }
    LaunchedEffect(Unit) {
        while (true) {
            ecoule = ((Navigateur.msDepuisLancement() - MoteurParcours.debutMs) / 1000).toInt()
            delay(500)
        }
    }
    val total = (av?.plan?.dureeMin ?: 0) * 60
    val nombre = av?.plan?.etapes?.size ?: 0
    Column(Modifier.fillMaxSize()) {
        Row(
            Modifier.fillMaxWidth().background(ENCADRE).padding(horizontal = 16.dp, vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Column(Modifier.weight(1f)) {
                Text("Étape ${MoteurParcours.rangEtape + 1}/$nombre : ${MoteurParcours.etape}", color = ENCRE, fontSize = 15.sp, fontWeight = FontWeight.Bold)
                Text("${mmss(ecoule)} / ${mmss(total)} · ne touchez pas l'écran", color = ENCRE, fontSize = 13.sp)
                val allume = av?.ecranAllume ?: ""
                if (!allume.startsWith("actif")) {
                    Text(
                        "Écran allumé non obtenu ($allume) : réglez Réglages › Luminosité et affichage › Verrouillage auto sur « Jamais » pendant l'essai.",
                        color = ROUGE, fontSize = 12.sp,
                    )
                }
            }
            OutlinedButton(onClick = { MoteurParcours.arreter() }) { Text("Arrêter") }
        }
        Box(Modifier.fillMaxWidth().weight(1f)) {
            when (MoteurParcours.scene) {
                Scene.STATUT -> Column(Modifier.fillMaxSize().padding(24.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    Text(MoteurParcours.etape, color = ENCRE, fontSize = 20.sp)
                    Text(MoteurParcours.statut, color = GRIS, fontSize = 15.sp)
                    av?.etapes?.lastOrNull()?.let { Text("Étape précédente : ${it.nom} — ${it.conclusion} (${it.dureeS} s)", color = GRIS, fontSize = 13.sp) }
                }
                Scene.LISTE -> EcranListe(MoteurParcours.etatListe)
                Scene.CARTE -> EcranCarte(MoteurParcours.etatCarte)
                Scene.SAISIE -> EcranSaisie()
                Scene.PHOTOS -> EcranPhotos()
                Scene.INFOS -> EcranInfos()
            }
        }
    }
}

/** Une question, trois gros boutons. */
@Composable
private fun LigneQuestion(q: Question, reponse: Reponse?, choisir: (Reponse) -> Unit) {
    Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
        Text(q.libelle, color = ENCRE, fontSize = 16.sp)
        Row(horizontalArrangement = Arrangement.spacedBy(6.dp), modifier = Modifier.fillMaxWidth()) {
            for (r in Reponse.entries) {
                val m = Modifier.weight(1f).height(52.dp)
                if (r == reponse) Button(onClick = { choisir(r) }, modifier = m) { Text(r.libelle, fontSize = 14.sp) }
                else OutlinedButton(onClick = { choisir(r) }, modifier = m) { Text(r.libelle, fontSize = 14.sp) }
            }
        }
    }
}

@Composable
private fun QuestionsRapides() {
    val reponses = remember { mutableStateMapOf<Question, Reponse>() }
    var saisie by remember { mutableStateOf(false) }
    val mesure = ClavierMesure.dernierChamp ?: ClavierMesure.derniere
    if (saisie) {
        Column(Modifier.fillMaxSize()) {
            Column(Modifier.fillMaxWidth().background(ENCADRE).padding(horizontal = 16.dp, vertical = 8.dp)) {
                Text(
                    "‹ Revenir aux questions",
                    color = ENCRE, fontSize = 16.sp,
                    modifier = Modifier.clickable { saisie = false }.padding(vertical = 6.dp),
                )
                Text("Tapez des accents dans « Nom », un copier-coller, la dictée (micro du clavier), puis touchez le dernier champ tout en bas.", color = ENCRE, fontSize = 13.sp)
                Text("Dernier champ : " + (ClavierMesure.dernierChamp?.enTexte() ?: "pas encore touché"), color = GRIS, fontSize = 12.sp)
            }
            Box(Modifier.fillMaxWidth().weight(1f)) { EcranSaisie() }
        }
        return
    }
    Column(
        Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp),
    ) {
        Text("Les mesures automatiques sont finies.", color = ENCRE, fontSize = 18.sp, fontWeight = FontWeight.Bold)
        Text("Quelques questions : ce que la sonde ne peut pas voir seule. Un toucher par question.", color = ENCRE, fontSize = 14.sp)
        Column(Modifier.fillMaxWidth().background(ENCADRE).padding(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
            Text("Essai de saisie (deux minutes)", color = ENCRE, fontSize = 16.sp)
            Text("Ouvrez l'essai, tapez, puis touchez le dernier champ tout en bas : la sonde mesure seule s'il reste au-dessus du clavier.", color = ENCRE, fontSize = 13.sp)
            Button(onClick = { saisie = true }, modifier = Modifier.height(52.dp)) { Text("Ouvrir l'essai de saisie") }
            Text("Mesure du clavier : " + (mesure?.enTexte() ?: "pas encore faite"), color = if (mesure?.visible == false && mesure.clavierPx > 0) ROUGE else GRIS, fontSize = 13.sp)
        }
        for (q in Question.entries.filter { it != Question.HORS_LIGNE }) {
            LigneQuestion(q, reponses[q]) { reponses[q] = it }
        }
        Column(Modifier.fillMaxWidth().background(ENCADRE).padding(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
            Text("Hors ligne", color = ENCRE, fontSize = 16.sp)
            Text(
                "Plus tard : passez en mode avion, fermez la sonde (balayez-la vers le haut dans le sélecteur d'applications), puis ouvrez-la depuis son icône. " +
                    "La sonde note seule l'ouverture hors ligne et son temps. Revenez ensuite dans « Parcours automatique » › « Voir son rapport » et envoyez-le, réseau rétabli.",
                color = ENCRE, fontSize = 13.sp,
            )
            ouvertureHorsLigneNotee()?.let { Text("Déjà notée : le ${it.date}, ${it.ms} ms.", color = VERT, fontSize = 13.sp) }
            LigneQuestion(Question.HORS_LIGNE, reponses[Question.HORS_LIGNE]) { reponses[Question.HORS_LIGNE] = it }
        }
        Button(
            onClick = { MoteurParcours.terminer(reponses.toMap(), ClavierMesure.dernierChamp ?: ClavierMesure.derniere) },
            modifier = Modifier.fillMaxWidth().height(60.dp),
        ) { Text("Terminer et voir le rapport", fontSize = 17.sp) }
    }
}

@Composable
private fun FinDuParcours() {
    val av = MoteurParcours.avancement ?: run {
        Text("Aucun parcours à montrer.", modifier = Modifier.padding(16.dp))
        return
    }
    val scope = rememberCoroutineScope()
    val chargement = remember { Navigateur.numeroChargement() }
    val verdicts = remember(av) { verdictsDuParcours(av, chargement, ouvertureHorsLigneNotee()) }
    var rapport by remember { mutableStateOf<Rapport?>(null) }
    var remarque by remember { mutableStateOf(Navigateur.lireReglage(Banc.REGLAGE_REMARQUE)) }
    var statut by remember { mutableStateOf("") }
    var ticket by remember { mutableStateOf("") }
    var envoiEnCours by remember { mutableStateOf(false) }
    val envoiPossible = remember { Navigateur.envoiDisponible() }
    // Construit d'avance : Copier et Partager partent du toucher sans rien attendre (iOS).
    LaunchedEffect(av) { rapport = rapportDuParcours(av) }

    Column(
        Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(10.dp),
    ) {
        Text(resumeVerdicts(verdicts), color = ENCRE, fontSize = 20.sp, fontWeight = FontWeight.Bold)
        val etat = when {
            av.etat == PARCOURS_FINI -> "Parcours de ${av.plan.dureeMin} min fini."
            av.etat == PARCOURS_ARRETE -> "Rapport partiel : parcours arrêté à l'étape « ${av.etapeCourante()} » après ${av.minutes()} min."
            else -> "Rapport partiel : " + (interruption(av, chargement)?.message() ?: "parcours en cours.")
        }
        Text(etat, color = ENCRE, fontSize = 14.sp)
        for (v in verdicts) {
            Row(Modifier.fillMaxWidth().background(ENCADRE).padding(10.dp)) {
                Text(v.point, color = ENCRE, fontSize = 15.sp, fontWeight = FontWeight.Bold, modifier = Modifier.width(30.dp))
                Column(Modifier.weight(1f)) {
                    Text(v.intitule, color = ENCRE, fontSize = 15.sp)
                    Text(
                        v.verdict,
                        color = when (v.verdict) { PASSE -> VERT; ECHOUE -> ROUGE; else -> GRIS },
                        fontSize = 15.sp, fontWeight = FontWeight.Bold,
                    )
                    Text(v.note, color = ENCRE.copy(alpha = 0.75f), fontSize = 12.sp)
                }
            }
        }
        // La remarque va avec le rapport : elle est rangée dans le rapport déjà prêt à chaque frappe.
        ChampRemarque(remarque, { remarque = it; Navigateur.ecrireReglage(Banc.REGLAGE_REMARQUE, it); rapport = rapport?.copy(remarque = it) })
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
            Button(
                enabled = envoiPossible && !envoiEnCours && rapport != null,
                onClick = {
                    val r = rapport ?: return@Button
                    envoiEnCours = true
                    statut = "Envoi en cours…"
                    scope.launch(start = CoroutineStart.UNDISPATCHED) {
                        try {
                            val resultat = ExportRapport.envoyer(r)
                            ticket = resultat.url ?: ""
                            if (resultat.url != null) { remarque = ""; Navigateur.ecrireReglage(Banc.REGLAGE_REMARQUE, "") }
                            statut = if (resultat.url != null) "Rapport envoyé. Merci !" else "${resultat.raison} Vous pouvez « Copier » ou « Partager »."
                        } finally { envoiEnCours = false }
                    }
                },
                modifier = Modifier.weight(1f).height(56.dp),
            ) { Text("Envoyer le rapport") }
        }
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
            OutlinedButton(
                enabled = rapport != null,
                onClick = {
                    val r = rapport ?: return@OutlinedButton
                    ExportRapport.copier(r)
                    scope.launch { delay(700); statut = "Presse-papiers : " + Navigateur.statutCopie().ifEmpty { "en cours…" } }
                },
                modifier = Modifier.weight(1f).height(52.dp),
            ) { Text("Copier") }
            OutlinedButton(
                enabled = rapport != null,
                onClick = {
                    val r = rapport ?: return@OutlinedButton
                    scope.launch(start = CoroutineStart.UNDISPATCHED) { statut = ExportRapport.partager(r) }
                },
                modifier = Modifier.weight(1f).height(52.dp),
            ) { Text("Partager") }
        }
        OutlinedButton(onClick = { MoteurParcours.recommencer() }, modifier = Modifier.fillMaxWidth().height(52.dp)) { Text("Recommencer") }
        if (!envoiPossible) Text("Envoi automatique indisponible dans cette version (« Copier » ou « Partager » restent possibles).", color = GRIS, fontSize = 13.sp)
        if (statut.isNotEmpty()) Text(statut, color = ENCRE, fontSize = 14.sp)
        if (ticket.isNotEmpty()) SelectionContainer { Text("Ticket : $ticket", color = ENCRE, fontSize = 14.sp) }
        Text(
            rapport?.let { "Rapport prêt : ${it.etapes.size} étapes, ${it.verdicts.size} verdicts, ${it.enTexte().length} caractères." } ?: "Rapport en préparation…",
            color = GRIS, fontSize = 12.sp,
        )
    }
}
