package com.example.lebiais.sonde

import androidx.compose.foundation.gestures.awaitEachGesture
import androidx.compose.foundation.gestures.awaitFirstDown
import androidx.compose.ui.Modifier
import androidx.compose.ui.input.pointer.PointerEventPass
import androidx.compose.ui.input.pointer.pointerInput

/**
 * Annonce au navigateur le clavier voulu (`inputmode`, `autocapitalize`) AU TOUCHER, avant que le champ
 * prenne le focus. iOS lit ces attributs quand le clavier s'ouvre : les poser dans `onFocusChanged`
 * arrive après, et le champ touché avait alors le mode du champ précédent (vu au rapport d'essai : la
 * majuscule automatique manquait sur « Nom » après un champ numérique). N'intercepte rien.
 */
fun Modifier.modeClavierAuToucher(inputMode: String, autoCapitalize: String): Modifier =
    pointerInput(inputMode, autoCapitalize) {
        awaitEachGesture {
            awaitFirstDown(requireUnconsumed = false, pass = PointerEventPass.Initial)
            Navigateur.modeClavier(inputMode, autoCapitalize)
        }
    }
