package com.example.lebiais.sonde

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.add
import kotlinx.serialization.json.booleanOrNull
import kotlinx.serialization.json.buildJsonArray
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.put
import kotlinx.serialization.json.putJsonArray
import kotlinx.serialization.json.putJsonObject

// Le rapport d'essai de la sonde : logique pure, sans navigateur. Assemblé par
// `RapportCourant.kt`, exporté par l'écran Infos (et par le parcours du lot B).

/** Limites de la fonction Edge `signaler` (supabase/functions/signaler/index.ts). */
const val LIMITE_TITRE = 120
const val LIMITE_DESCRIPTION = 5000
const val LIMITE_CONTEXTE = 500
const val LIMITE_JOURNAL = 50_000
/** La remarque du testeur : au plus ce nombre de caractères dans le rapport, dont la moitié au plus dans la description. */
const val LIMITE_REMARQUE = 10_000
const val LIMITE_REMARQUE_DESCRIPTION = 1500

/** Les dernières lignes du relevé reprises dans le rapport. */
const val DERNIERES_LIGNES_DU_RAPPORT = 120

/** Le résultat d'une étape d'essai (une série de photos, un point du parcours…). */
data class ResultatEtape(val nom: String, val verdict: String, val mesures: List<Pair<String, String>> = emptyList())

/** Un point de la grille (plans/2026-11-05-pwa-ios-etape-0-grille.md) et son verdict. */
data class VerdictGrille(val point: String, val intitule: String, val verdict: String, val note: String = "")

data class Rapport(
    val build: String,
    /** "wasm" ou "js". */
    val version: String,
    /** Date locale lisible, « 2026-11-21 14:03 » : les dix premiers caractères vont dans le titre. */
    val date: String,
    /** Libellé libre « Testeur / appareil ». */
    val testeur: String,
    /** « Version d'iOS indiquée par le testeur », texte libre. */
    val iosIndique: String,
    val appareil: Appareil,
    val environnement: List<Pair<String, String>>,
    val etapes: List<ResultatEtape>,
    val verdicts: List<VerdictGrille>,
    /** Les lignes brutes du relevé (échantillons et événements), les plus anciennes d'abord. */
    val releve: List<String>,
    /** Le journal des chargements, une ligne par chargement. */
    val chargements: List<String>,
    /** Ce que le testeur a voulu ajouter, texte libre (facultatif). */
    val remarque: String = "",
) {
    private val remarqueNette: String get() = remarque.trim().take(LIMITE_REMARQUE)

    private val echantillons by lazy { releve.mapNotNull { Echantillon.lire(it) } }
    private val creux by lazy {
        releve.filter { l -> Echantillon.lire(l)?.let { it.fpsMin < SEUIL_CREUX_FPS || it.geleeMs >= SEUIL_GEL_MS } == true }
    }
    private val evenements by lazy { evenementsDuReleve(releve) }

    /** La ligne de résumé du relevé (nombre, moyenne, pire, pause max, creux). */
    fun resumeReleve(): String = resumeDuReleve(echantillons).enTexte(derniers = 0).lines().first()

    /** Le rapport complet, en Markdown. */
    fun enTexte(): String = composer(minOf(DERNIERES_LIGNES_DU_RAPPORT, releve.size), creux.size, retirees = 0, creuxRetires = 0)

    /**
     * Le rapport en [limite] caractères au plus. On garde l'en-tête, les verdicts et les
     * creux ; on retire d'abord les plus anciennes des dernières lignes, puis les plus
     * anciens creux, et on le dit. En dernier recours, on coupe la fin.
     */
    fun enTexte(limite: Int): String {
        val derniers = minOf(DERNIERES_LIGNES_DU_RAPPORT, releve.size)
        var garde = derniers
        var gardeCreux = creux.size
        var t = composer(garde, gardeCreux, 0, 0)
        while (t.length > limite && garde > 0) {
            garde = maxOf(0, garde - aRetirer(t.length - limite, releve.takeLast(garde)))
            t = composer(garde, gardeCreux, derniers - garde, 0)
        }
        while (t.length > limite && gardeCreux > 0) {
            gardeCreux = maxOf(0, gardeCreux - aRetirer(t.length - limite, creux.takeLast(gardeCreux)))
            t = composer(garde, gardeCreux, derniers - garde, creux.size - gardeCreux)
        }
        return couper(t, limite)
    }

    /** Combien des plus anciennes [lignes] retirer pour gagner [exces] caractères (au moins une). */
    private fun aRetirer(exces: Int, lignes: List<String>): Int {
        var gagne = 0
        var n = 0
        // La note « … retirées pour tenir … » ajoute quelques caractères : marge de 100.
        while (n < lignes.size && gagne < exces + 100) gagne += lignes[n++].length + 1
        return maxOf(1, n)
    }

    private fun composer(derniers: Int, nCreux: Int, retirees: Int, creuxRetires: Int): String = buildString {
        appendLine("# Sonde PWA — rapport")
        appendLine()
        appendLine("- Date : $date")
        appendLine("- Build : $build ($version)")
        appendLine("- Testeur / appareil : ${testeur.ifBlank { "non indiqué" }}")
        appendLine("- Version d'iOS indiquée par le testeur : ${iosIndique.ifBlank { "non indiquée" }}")
        appendLine("- Appareil (user agent) : ${appareil.resume()}")
        appareil.note?.let { appendLine("- Note : $it") }
        appendLine()
        if (remarqueNette.isNotEmpty()) {
            appendLine("## Remarque du testeur")
            appendLine()
            appendLine(remarqueNette)
            appendLine()
        }
        appendLine("## Verdicts de la grille")
        if (verdicts.isEmpty()) appendLine("Aucun verdict (aucun parcours lancé).")
        for (v in verdicts) appendLine("- ${v.point}. ${v.intitule} : ${v.verdict}" + if (v.note.isNotBlank()) " — ${v.note}" else "")
        appendLine()
        appendLine("## Étapes")
        if (etapes.isEmpty()) appendLine("Aucune étape enregistrée.")
        for (e in etapes) {
            appendLine("### ${e.nom} — ${e.verdict}")
            for ((k, v) in e.mesures) appendLine("- $k : $v")
        }
        appendLine()
        appendLine("## Environnement")
        for ((k, v) in environnement) appendLine("- $k : $v")
        appendLine()
        appendLine("## Relevé de fluidité")
        appendLine("Colonnes : heure|écran|fps|fps min|photos|fiches|Mo décodés|pause max (ms)")
        appendLine(resumeReleve())
        appendLine()
        val noteCreux = if (creuxRetires > 0) " ; les $creuxRetires plus anciens retirés pour tenir en ${milliers(LIMITE_JOURNAL)} caractères" else ""
        appendLine("### Creux (${creux.size}$noteCreux)")
        for (l in creux.takeLast(nCreux)) appendLine(l)
        appendLine()
        appendLine("### Événements (${evenements.size})")
        for (l in evenements) appendLine(l)
        appendLine()
        val noteLignes = if (retirees > 0) " ; les $retirees plus anciennes retirées pour tenir en ${milliers(LIMITE_JOURNAL)} caractères" else ""
        appendLine("### Dernières lignes ($derniers dernières lignes sur ${releve.size}$noteLignes)")
        for (l in releve.takeLast(derniers)) appendLine(l)
        appendLine()
        appendLine("## Chargements")
        for (l in chargements) appendLine(l)
    }

    /** Le rapport en JSON (mêmes données que le texte, relevé compris). */
    fun enJson(): String {
        val objet = buildJsonObject {
            put("build", build)
            put("version", version)
            put("date", date)
            put("testeur", testeur)
            put("iosIndique", iosIndique)
            put("remarque", remarqueNette)
            putJsonObject("appareil") {
                put("appareil", appareil.appareil)
                put("systeme", appareil.systeme)
                put("navigateur", appareil.navigateur)
                put("ios", appareil.ios)
                appareil.note?.let { put("note", it) }
            }
            putJsonObject("environnement") { for ((k, v) in environnement) put(k, v) }
            putJsonArray("etapes") {
                for (e in etapes) add(buildJsonObject {
                    put("nom", e.nom)
                    put("verdict", e.verdict)
                    putJsonObject("mesures") { for ((k, v) in e.mesures) put(k, v) }
                })
            }
            putJsonArray("verdicts") {
                for (v in verdicts) add(buildJsonObject {
                    put("point", v.point)
                    put("intitule", v.intitule)
                    put("verdict", v.verdict)
                    put("note", v.note)
                })
            }
            putJsonObject("releve") {
                put("total", releve.size)
                put("resume", resumeReleve())
                put("creux", JsonArray(creux.map(::JsonPrimitive)))
                put("evenements", JsonArray(evenements.map(::JsonPrimitive)))
                put("dernieres", JsonArray(releve.takeLast(DERNIERES_LIGNES_DU_RAPPORT).map(::JsonPrimitive)))
            }
            put("chargements", JsonArray(chargements.map(::JsonPrimitive)))
        }
        return JSON_LISIBLE.encodeToString(JsonElement.serializer(), objet)
    }

    /** « Sonde PWA — rapport <appareil> <OS> <date> » ; l'OS du testeur passe avant celui du user agent. */
    fun titre(): String {
        val os = when {
            iosIndique.isNotBlank() -> "iOS " + iosIndique.trim().removePrefix("iOS").removePrefix("iPadOS").trim()
            appareil.note == null && appareil.systeme.any { it.isDigit() } -> appareil.systeme
            else -> ""
        }
        return listOf("Sonde PWA — rapport", appareil.appareil, os, date.take(10))
            .filter { it.isNotBlank() }.joinToString(" ").take(LIMITE_TITRE)
    }

    /** Le résumé pour un humain : verdicts, étapes, relevé. Le reste est dans le journal. */
    fun description(): String = couper(buildString {
        appendLine("Rapport de la sonde PWA, build $build ($version), $date.")
        appendLine("Appareil : ${appareil.resume()} · iOS indiqué par le testeur : ${iosIndique.ifBlank { "non indiqué" }} · testeur : ${testeur.ifBlank { "non indiqué" }}.")
        appendLine()
        if (remarqueNette.isNotEmpty()) {
            appendLine("**Remarque du testeur**")
            if (remarqueNette.length > LIMITE_REMARQUE_DESCRIPTION) {
                appendLine(remarqueNette.take(LIMITE_REMARQUE_DESCRIPTION).trimEnd() + " … (remarque tronquée ici : le texte entier est dans le journal technique)")
            } else {
                appendLine(remarqueNette)
            }
            appendLine()
        }
        appendLine("**Verdicts**")
        if (verdicts.isEmpty()) appendLine("Aucun verdict (aucun parcours lancé).")
        for (v in verdicts) appendLine("- ${v.point}. ${v.intitule} : ${v.verdict}" + if (v.note.isNotBlank()) " — ${v.note}" else "")
        appendLine()
        appendLine("**Étapes**")
        if (etapes.isEmpty()) appendLine("Aucune étape enregistrée.")
        for (e in etapes) {
            val mesures = e.mesures.joinToString(" ; ") { "${it.first} : ${it.second}" }
            appendLine("- ${e.nom} : ${e.verdict}" + if (mesures.isNotEmpty()) " ($mesures)" else "")
        }
        appendLine()
        appendLine("**Relevé** : ${resumeReleve()}")
        appendLine()
        append("Le rapport complet (environnement, creux, dernières lignes, chargements) est dans le journal technique.")
    }, LIMITE_DESCRIPTION)

    /** D'où vient le rapport, en une ligne. */
    fun contexte(): String = couper(
        "Sonde PWA $version, build $build · ${appareil.resume()} · iOS indiqué : ${iosIndique.ifBlank { "non" }} · ${testeur.ifBlank { "testeur non indiqué" }}",
        LIMITE_CONTEXTE,
    )

    /** Le corps attendu par `signaler`, chaque champ dans sa limite. */
    fun pourSignaler(): SignalementSonde =
        SignalementSonde("sonde", titre(), description(), contexte(), enTexte(LIMITE_JOURNAL))
}

/** Ce que l'on envoie à la fonction Edge `signaler`. */
data class SignalementSonde(val type: String, val titre: String, val description: String, val contexte: String, val journal: String)

private val JSON_LISIBLE = Json { prettyPrint = true }

private fun milliers(n: Int): String = n.toString().reversed().chunked(3).joinToString(" ").reversed()

private const val TRONQUE = "\n… (tronqué)"

/** [texte] en [max] caractères au plus, en disant qu'il est tronqué. */
internal fun couper(texte: String, max: Int): String =
    if (texte.length <= max) texte else texte.take(maxOf(0, max - TRONQUE.length)) + TRONQUE.take(max)

/** Le résultat d'un envoi : l'URL du ticket, ou la raison de l'échec en une phrase. */
data class ResultatEnvoi(val url: String?, val raison: String?)

/** Lit la réponse de `sonde.envoyerRapport` : « O<url> » ou « E<code>|<détail> ». */
fun lireResultatEnvoi(reponse: String): ResultatEnvoi {
    if (reponse.startsWith("O")) return ResultatEnvoi(reponse.substring(1), null)
    val corps = reponse.removePrefix("E")
    val code = corps.substringBefore('|')
    val detail = corps.substringAfter('|', "").trim()
    val raison = when (code) {
        "config" -> "Envoi automatique indisponible dans cette version (pas de configuration) : utilisez « Copier » ou « Partager »."
        "reseau" -> "Le serveur n'a pas répondu (pas de réseau, ou appel bloqué par le navigateur : CORS)" + (if (detail.isNotEmpty()) " : $detail." else ".")
        "session" -> "Impossible d'ouvrir une session anonyme" + (if (detail.isNotEmpty()) " ($detail)." else ".")
        "401" -> "Session refusée par le serveur (401) : réessayer, la session sera renouvelée."
        "429" -> "Limite atteinte : 5 rapports par 24 h depuis cet appareil."
        "400" -> "Rapport refusé par le serveur (400" + (if (detail.isNotEmpty()) " : $detail" else "") + ")."
        else -> "Erreur du serveur ($code" + (if (detail.isNotEmpty()) " : $detail" else "") + ")."
    }
    return ResultatEnvoi(null, raison)
}

/**
 * Le contrôle du précache rendu par le Service Worker (voir web/sw.js, message
 * « controlePrecache ») : `{"build","version","requis":[[chemin, présent]…],
 * "optionnels":[…],"autre":[…]}`, ou `{"etat": "…"}` quand il n'a pas pu se faire.
 */
fun lireControlePrecache(json: String): String {
    val objet: JsonObject = try {
        Json.parseToJsonElement(json).jsonObject
    } catch (e: Exception) {
        return "illisible : ${json.take(80)}"
    }
    objet["etat"]?.let { return it.jsonPrimitive.content }
    fun liste(nom: String): List<Pair<String, Boolean>> = objet[nom]?.jsonArray?.map {
        val p = it.jsonArray
        p[0].jsonPrimitive.content to (p[1].jsonPrimitive.booleanOrNull == true)
    } ?: emptyList()
    val requis = liste("requis")
    val optionnels = liste("optionnels")
    val autre = liste("autre")
    val manquants = requis.filter { !it.second }.map { it.first }
    return "build ${objet["build"]?.jsonPrimitive?.content} (${objet["version"]?.jsonPrimitive?.content}) : " +
        "${requis.count { it.second }}/${requis.size} requis en cache · " +
        "optionnels ${optionnels.count { it.second }}/${optionnels.size} · " +
        "autre version ${autre.count { it.second }}/${autre.size} (se met en cache à son premier chargement)" +
        if (manquants.isNotEmpty()) " · manquent : ${manquants.joinToString(", ")}" else ""
}
